-- Packages 08-15: SKU reads through the API entry point
--
-- GENERATED by rds/deploy/build.sh from rds/database/. Do not edit -
-- change the sources and rebuild. Run in APEX: SQL Workshop > SQL Scripts.

-- ==== 20_packages/08_ie_mfcs_sku.sql

-- Reconciles the SKUs a request needs against the SKUs a style actually has.
--
-- Why this exists: PLM does not know about SKUs. It sends MODIFY_STYLE or an
-- order operation naming a style and a colour, and expects the integration to
-- work out the rest.
--
-- And a colour change cannot be applied to an existing SKU. In the RMS model a
-- diff combination *defines* the item, so a new colour means new children. This
-- was confirmed against the tenant: PUT items/update with a changed diff1
-- returned HTTP 200 SUCCESS and left the item untouched. MFCS does not reject
-- the change, it silently ignores it - so an integration that simply forwards a
-- colour change reports success while nothing happens.
--
-- Everything here is read-only analysis. Creating the missing children is the
-- orchestrator's job; this package tells it what is missing.

create or replace package ie_mfcs_sku authid definer as

    -- Children of a style, read through RmsReSTServices Item/itemDetail, which
    -- returns a style together with its children in one call.
    -- Returns {"skus":[{"item","diff1","diff2","status"}], "available":true|false}
    function existing_skus(p_style in varchar2) return clob;

    -- Compares the colour and size curve a request needs against what the style
    -- already has, and reports which SKUs exist and which would have to be
    -- created before the request can proceed.
    --
    -- p_sizes is a colon-separated list of display sizes, e.g. '7:8:9'. They are
    -- mapped to MFCS size diffs through MAP.SIZE.* the same way the payload
    -- mapper does, so this and the outbound payload cannot disagree.
    function resolve_gap(
        p_style  in varchar2,
        p_colour in varchar2,
        p_sizes  in varchar2
    ) return clob;

    -- The attributes a new child has to inherit from the style it joins.
    --
    -- A child must sit in its parent's merchandise hierarchy, and the document that
    -- arrives with an order does not carry one: PLM names a style and expects the
    -- integration to know the rest. The same read supplies the supplier, cost and
    -- origin country to fall back on when the document does not name them, which
    -- matters because MFCS will not approve an item that has no sourcing.
    --
    -- This reads itemDetail, not foundation/item, and the difference is not a
    -- preference. foundation/item is fed by the publish queue: it answered 404 for a
    -- style that had just been created and approved, while itemDetail returned it in
    -- full. Anything that has to work on a style this integration created moments
    -- ago cannot be built on the feed.
    --
    -- itemDetail is a third vocabulary, after the item feed's and the write
    -- services'. It says classAttribute for class, itemDesc/shortDesc for the
    -- descriptions, primarySuppInd for primarySupplierInd and originCountryId for
    -- originCountry. Translating is this function's job, so callers see one set of
    -- names. It carries no costZoneGroupId, standardUom or storeOrderMultiple; those
    -- keys come back absent and the payload builders fall back to configuration.
    --
    -- Returns {"available":true|false, "dept","class","subclass","status",
    -- "originalRetail","itemDescription","shortDescription","supplier","unitCost",
    -- "originCountry"}.
    function style_attributes(p_style in varchar2) return clob;
end ie_mfcs_sku;
/

create or replace package body ie_mfcs_sku as

    -- Identity. Every front end that talks to this controller sends the tenant's
    -- own differentiator ID, so there is nothing to translate. This used to read
    -- MAP.SIZE.* config, which meant a display size like "7" had to be mapped to
    -- "070" - and left eight size descriptions ambiguous, because the tenant has
    -- three differentiators described "16".
    function size_diff(p_display in varchar2) return varchar2 is
    begin
        return p_display;
    end;

    -- Identity, for the same reason as size_diff. This was already effectively
    -- identity: every MAP.COLOUR.* row mapped a code to itself.
    function colour_diff(p_colour in varchar2) return varchar2 is
    begin
        return p_colour;
    end;

    function existing_skus(p_style in varchar2) return clob is
        l_status number;
        l_body clob;
        l_arr json_array_t;
        l_row json_object_t;
        l_out json_object_t := json_object_t();
        l_skus json_array_t := json_array_t();
        l_sku json_object_t;
    begin
        l_body := ie_mfcs_client.get_json(
            '/RmsReSTServices/services/private/Item/itemDetail?item=' || p_style, l_status);

        if l_status not between 200 and 299 then
            l_out.put('available', false);
            l_out.put('skus', json_array_t());
            l_out.put('message', 'itemDetail returned HTTP ' || l_status);
            return l_out.to_clob;
        end if;

        l_arr := json_array_t.parse(l_body);
        for i in 0 .. l_arr.get_size - 1 loop
            l_row := treat(l_arr.get(i) as json_object_t);
            -- The response is not ordered parent-first, so match the relationship.
            if l_row.get_string('itemParent') = p_style then
                l_sku := json_object_t();
                l_sku.put('item', l_row.get_string('item'));
                l_sku.put('diff1', l_row.get_string('diff1'));
                l_sku.put('diff2', l_row.get_string('diff2'));
                l_sku.put('status', l_row.get_string('status'));
                l_skus.append(l_sku);
            end if;
        end loop;

        l_out.put('available', true);
        l_out.put('skus', l_skus);
        return l_out.to_clob;
    exception
        when others then
            l_out := json_object_t();
            l_out.put('available', false);
            l_out.put('skus', json_array_t());
            l_out.put('message', substr(sqlerrm, 1, 300));
            return l_out.to_clob;
    end;

    function resolve_gap(
        p_style  in varchar2,
        p_colour in varchar2,
        p_sizes  in varchar2
    ) return clob is
        l_root json_object_t := json_object_t();
        l_existing json_object_t;
        l_skus json_array_t;
        l_sku json_object_t;
        l_required json_array_t := json_array_t();
        l_missing json_array_t := json_array_t();
        l_entry json_object_t;
        l_colour_diff varchar2(120) := colour_diff(p_colour);
        l_sizes apex_t_varchar2;
        l_size_diff varchar2(120);
        l_match varchar2(30);
        l_have number := 0;
    begin
        l_root.put('style', p_style);
        l_root.put('colour', p_colour);
        l_root.put('colourDiff', l_colour_diff);

        l_existing := json_object_t.parse(existing_skus(p_style));
        if not l_existing.get_boolean('available') then
            l_root.put('resolved', false);
            l_root.put('message', l_existing.get_string('message'));
            return l_root.to_clob;
        end if;
        l_skus := l_existing.get_array('skus');

        l_sizes := apex_string.split(p_sizes, ':');
        for i in 1 .. l_sizes.count loop
            if l_sizes(i) is not null then
                l_size_diff := size_diff(l_sizes(i));
                l_match := null;

                -- A SKU matches only when BOTH diffs match. Same colour, different
                -- size is a different SKU, and so is the reverse.
                for j in 0 .. l_skus.get_size - 1 loop
                    l_sku := treat(l_skus.get(j) as json_object_t);
                    if l_sku.get_string('diff1') = l_colour_diff
                       and l_sku.get_string('diff2') = l_size_diff then
                        l_match := l_sku.get_string('item');
                        exit;
                    end if;
                end loop;

                l_entry := json_object_t();
                l_entry.put('size', l_sizes(i));
                l_entry.put('sizeDiff', l_size_diff);
                l_entry.put('colourDiff', l_colour_diff);
                l_entry.put('sku', l_match);
                l_entry.put('mappingFound', l_size_diff is not null);
                l_entry.put('status', case when l_match is not null then 'EXISTS' else 'MISSING' end);
                l_required.append(l_entry);

                if l_match is not null then
                    l_have := l_have + 1;
                else
                    l_missing.append(l_entry);
                end if;
            end if;
        end loop;

        l_root.put('resolved', true);
        l_root.put('existingSkuCount', l_skus.get_size);
        l_root.put('required', l_required);
        l_root.put('missing', l_missing);
        l_root.put('haveCount', l_have);
        l_root.put('missingCount', l_missing.get_size);
        l_root.put('complete', l_missing.get_size = 0);
        l_root.put('note',
            case when l_missing.get_size = 0
                 then 'The style already carries every colour/size combination this request needs.'
                 else 'A colour change cannot be applied to an existing SKU - MFCS returns SUCCESS '
                      || 'and ignores it. The missing combinations must be created as new children '
                      || 'before the request can proceed.'
            end);
        return l_root.to_clob;
    end;

    function style_attributes(p_style in varchar2) return clob is
        l_status number;
        l_body clob;
        l_arr json_array_t;
        l_row json_object_t;
        l_item json_object_t;
        l_suppliers json_array_t;
        l_supplier json_object_t;
        l_countries json_array_t;
        l_country json_object_t;
        l_out json_object_t := json_object_t();

        -- json_object_t.put stores an explicit null for a null bind, which then reads
        -- back as present-but-null. Absent is the honest answer when the tenant did
        -- not send the field, and it is what lets the payload builders fall back to
        -- configuration for the few attributes itemDetail does not carry.
        procedure put_str(p_name in varchar2, p_value in varchar2) is
        begin
            if p_value is not null then
                l_out.put(p_name, p_value);
            end if;
        end;

        procedure put_num(p_name in varchar2, p_value in number) is
        begin
            if p_value is not null then
                l_out.put(p_name, p_value);
            end if;
        end;
    begin
        l_body := ie_mfcs_client.get_json(
            '/RmsReSTServices/services/private/Item/itemDetail?item=' || p_style, l_status);

        if l_status not between 200 and 299 then
            l_out.put('available', false);
            l_out.put('message', 'itemDetail returned HTTP ' || l_status);
            return l_out.to_clob;
        end if;

        l_arr := json_array_t.parse(l_body);
        for i in 0 .. l_arr.get_size - 1 loop
            l_row := treat(l_arr.get(i) as json_object_t);
            -- The parent is the row that is the item itself; the rest are its
            -- children. The array is not ordered parent-first.
            if l_row.get_string('item') = p_style then
                l_item := l_row;
                exit;
            end if;
        end loop;

        if l_item is null then
            l_out.put('available', false);
            l_out.put('message', 'itemDetail returned no row for item ' || p_style);
            return l_out.to_clob;
        end if;

        l_out.put('available', true);
        put_str('item', l_item.get_string('item'));
        put_num('itemLevel', l_item.get_number('itemLevel'));
        put_num('dept', l_item.get_number('dept'));
        -- classAttribute, not class: itemDetail is a third vocabulary again, after
        -- the item feed's and the write services'. See the header comment.
        put_num('class', l_item.get_number('classAttribute'));
        put_num('subclass', l_item.get_number('subclass'));
        put_str('status', l_item.get_string('status'));
        put_num('originalRetail', l_item.get_number('originalRetail'));
        put_str('itemDescription', l_item.get_string('itemDesc'));
        put_str('shortDescription', l_item.get_string('shortDesc'));

        -- Take the primary supplier, falling back to the first row present. A style
        -- with no supplier at all is legitimate here: the caller decides whether the
        -- inbound document covers the gap.
        if l_item.has('itemSupplier') then
            l_suppliers := l_item.get_array('itemSupplier');
            for i in 0 .. nvl(l_suppliers.get_size, 0) - 1 loop
                l_supplier := treat(l_suppliers.get(i) as json_object_t);
                if i = 0 or nvl(l_supplier.get_string('primarySuppInd'), 'N') = 'Y' then
                    put_num('supplier', l_supplier.get_number('supplier'));

                    if l_supplier.has('itemSupplierCountry') then
                        l_countries := l_supplier.get_array('itemSupplierCountry');
                        for j in 0 .. nvl(l_countries.get_size, 0) - 1 loop
                            l_country := treat(l_countries.get(j) as json_object_t);
                            if j = 0 or nvl(l_country.get_string('primaryCountryInd'), 'N') = 'Y' then
                                put_str('originCountry', l_country.get_string('originCountryId'));
                                put_num('unitCost', l_country.get_number('unitCost'));
                            end if;
                        end loop;
                    end if;
                end if;
            end loop;
        end if;

        return l_out.to_clob;
    exception
        when others then
            l_out := json_object_t();
            l_out.put('available', false);
            l_out.put('message', substr(sqlerrm, 1, 300));
            return l_out.to_clob;
    end;
end ie_mfcs_sku;
/

-- ==== 20_packages/09_ie_mfcs_recovery.sql

-- Resolves the outcome of ambiguous calls by correlation ID.
--
-- When a transport error leaves a step OUTCOME_UNKNOWN, the truth is in the
-- tenant, not in this database. This asks MFCS's operation-status service what
-- happened to the correlation id the attempt journalled: SUCCESS marks the
-- step done, FAILURE marks it failed, and no record at all means the call
-- never landed and the step can simply run again.

create or replace package ie_mfcs_recovery authid definer as
    -- Resolves the most recent OUTCOME_UNKNOWN attempt of one step. Returns
    -- SUCCEEDED, FAILED, NO_RECORD (safe to re-run), MANUAL_REVIEW (still
    -- ambiguous - the request is parked), or NO_UNKNOWN_ATTEMPT.
    function resolve_step(
        p_action_request_id in varchar2,
        p_step_code         in varchar2
    ) return varchar2;
end ie_mfcs_recovery;
/

create or replace package body ie_mfcs_recovery as
    function resolve_step(
        p_action_request_id in varchar2,
        p_step_code         in varchar2
    ) return varchar2 is
        l_correlation_id varchar2(80);
        l_status_response clob;
        l_status varchar2(30);
        l_response_code number;
        l_result_count number;
    begin
        select correlation_id
          into l_correlation_id
          from (
              select correlation_id
                from ie_mfcs_prd_step_attempt
               where action_request_id = p_action_request_id
                 and step_code = p_step_code
                 and attempt_status = 'OUTCOME_UNKNOWN'
               order by attempt_number desc
          )
         where rownum = 1;

        l_status_response := ie_mfcs_client.correlation_status(p_action_request_id, l_correlation_id);

        select json_value(l_status_response, '$.status' returning varchar2(30) null on error),
               json_value(l_status_response, '$.items[0].responseCode' returning number null on error),
               json_value(l_status_response, '$.count' returning number null on error)
          into l_status, l_response_code, l_result_count
          from dual;

        if l_status is null then
            if nvl(l_result_count, 0) = 0 then
                l_status := 'NO_RECORD';
            elsif l_response_code between 200 and 299 then
                l_status := 'SUCCESS';
            elsif l_response_code >= 400 then
                l_status := 'FAILURE';
            else
                l_status := 'UNKNOWN';
            end if;
        end if;

        if l_status = 'SUCCESS' then
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'SUCCEEDED');
            return 'SUCCEEDED';
        elsif l_status = 'FAILURE' then
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'FAILED', null, 'MFCS_REPORTED_FAILURE', 'MFCS operation-status service reported failure.');
            return 'FAILED';
        elsif l_status = 'NO_RECORD' then
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'PENDING');
            return 'NO_RECORD';
        else
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'OUTCOME_UNKNOWN', null, 'OUTCOME_UNKNOWN', 'MFCS operation outcome is still ambiguous.');
            ie_mfcs_request.set_request_status(p_action_request_id, 'MANUAL_REVIEW', ie_mfcs_request.build_status_response(p_action_request_id, 'MANUAL_REVIEW'));
            return 'MANUAL_REVIEW';
        end if;
    exception
        when no_data_found then
            return 'NO_UNKNOWN_ATTEMPT';
    end;
end ie_mfcs_recovery;
/

-- ==== 20_packages/10_ie_mfcs_orchestrator.sql

-- Request execution: walks the step graph, resolves each step to an MFCS
-- endpoint and method, sends the payload, and journals the outcome.
--
-- Execution is a loop over ie_mfcs_step.first_runnable_step, so resume and first
-- run are the same code path: whatever is not yet SUCCEEDED runs next. Every
-- operation sends its whole write set - see initialize_steps in ie_mfcs_step for
-- why - and the create-versus-update choice for each step is made here, in
-- endpoint_for_step, from the operation name alone.
--
-- ENSURE_STYLE_SKUS is the one step handled inline rather than through the
-- endpoint table: what it sends depends on what the tenant already holds.

create or replace package ie_mfcs_orchestrator authid definer as
    -- Runs every runnable step of a registered request, in sequence, until
    -- the graph is exhausted or a step fails. Sets the request's final status
    -- and stores the response document a duplicate submission will replay.
    procedure execute_request(
        p_action_request_id in varchar2
    );

    -- Resume is execute: the loop picks up from the first step that has not
    -- succeeded. Kept as a named entry point so the API reads honestly.
    procedure resume_request(
        p_action_request_id in varchar2
    );

    -- How one step reaches MFCS: the IE_MFCS_CFG_SETTING endpoint key, the HTTP method, and
    -- the ie_mfcs_payload mapper that builds the body. One record resolved by one
    -- case statement, so the three can never disagree - they used to be three
    -- parallel case statements over the same step codes, which nothing forced
    -- to stay in step. All fields null means the step is local (no MFCS call).
    type t_step_resolution is record (
        endpoint_key varchar2(200),
        http_method  varchar2(10),
        mapper_name  varchar2(80)
    );

    -- Pure resolver, exposed so the preview layer can describe the planned MFCS
    -- calls without duplicating the mapping. No side effects.
    function resolve_step(
        p_step_code in varchar2,
        p_operation in varchar2
    ) return t_step_resolution;

    function payload_for_step(
        p_action_request_id in varchar2,
        p_step_code         in varchar2
    ) return clob;
end ie_mfcs_orchestrator;
/

create or replace package body ie_mfcs_orchestrator as
    function request_payload(p_action_request_id in varchar2) return clob is
        l_payload clob;
    begin
        select request_payload
          into l_payload
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;
        return l_payload;
    end;

    function operation_name(p_action_request_id in varchar2) return varchar2 is
        l_operation varchar2(30);
    begin
        select operation_name
          into l_operation
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;
        return l_operation;
    end;

    function any_succeeded(p_action_request_id in varchar2) return boolean is
        l_count number;
    begin
        select count(*)
          into l_count
          from ie_mfcs_prd_request_step
         where action_request_id = p_action_request_id
           and step_status = 'SUCCEEDED'
           and step_code <> 'VALIDATE_REQUEST';
        return l_count > 0;
    end;

    procedure persist_item_numbers(
        p_action_request_id in varchar2,
        p_response          in clob
    ) is
        l_payload clob := request_payload(p_action_request_id);
        l_source_system varchar2(60) := ie_mfcs_payload.source_system(l_payload);
        l_source_style_ref varchar2(120) := ie_mfcs_payload.source_style_ref(l_payload);
        l_style_no varchar2(30);
        l_sku_no varchar2(30);
        l_response_obj json_object_t;
        l_items json_array_t;
    begin
        select coalesce(
                   json_value(p_response, '$.STYLE' returning varchar2(30) null on error),
                   json_value(p_response, '$.items[0].item' returning varchar2(30) null on error)
               )
          into l_style_no
          from dual;

        ie_mfcs_request.save_generated_identifier(
            p_action_request_id => p_action_request_id,
            p_source_system => l_source_system,
            p_source_style_ref => l_source_style_ref,
            p_mfcs_style_no => l_style_no
        );

        l_response_obj := json_object_t.parse(p_response);
        if l_response_obj.has('items') then
            l_items := l_response_obj.get_array('items');
            for v in ie_mfcs_payload.c_size_curve(l_payload) loop
                -- items[0] is the style; the children follow in curve order.
                l_sku_no := treat(l_items.get(v.rn) as json_object_t).get_string('item');
                ie_mfcs_request.save_generated_identifier(
                    p_action_request_id => p_action_request_id,
                    p_source_system => l_source_system,
                    p_source_style_ref => l_source_style_ref,
                    p_mfcs_style_no => l_style_no,
                    p_source_variant_ref => v.source_variant_ref,
                    p_mfcs_sku_no => l_sku_no,
                    p_sku_size => v.sku_size,
                    p_sku_width => v.sku_width
                );
            end loop;
        else
            -- The response echoes the document's own SIZE_CURVE_DETAIL shape,
            -- so the same cursor reads it.
            for v in ie_mfcs_payload.c_size_curve(p_response) loop
                ie_mfcs_request.save_generated_identifier(
                    p_action_request_id => p_action_request_id,
                    p_source_system => l_source_system,
                    p_source_style_ref => l_source_style_ref,
                    p_mfcs_style_no => l_style_no,
                    p_source_variant_ref => v.source_variant_ref,
                    p_mfcs_sku_no => v.sku_id,
                    p_sku_size => v.sku_size,
                    p_sku_width => v.sku_width
                );
            end loop;
        end if;
    end;

    function first_reserved_item(p_response in clob) return varchar2 is
        l_item varchar2(30);
    begin
        select coalesce(
                   json_value(p_response, '$.items[0].item' returning varchar2(30) null on error),
                   json_value(p_response, '$.item' returning varchar2(30) null on error),
                   json_value(p_response, '$.STYLE' returning varchar2(30) null on error)
               )
          into l_item
          from dual;

        if l_item is null then
            raise_application_error(-20830, 'MFCS item-number reservation response did not contain an item number.');
        end if;

        return l_item;
    end;

    -- Records the item numbers the document brought with it, in place of asking
    -- MFCS for numbers. Makes no outbound call: the numbers are already decided,
    -- and itemNumbers/reserve would only issue different ones.
    --
    -- Nothing about the numbers is checked here. Validation has already run - it
    -- is the step before this one - and it is the place that knows the rules and
    -- can report a breach against the field that broke it. Re-checking here would
    -- be a second opinion able to disagree with the first.
    procedure assign_supplied_item_numbers(
        p_action_request_id in varchar2,
        p_payload           in clob,
        p_style_no          in varchar2
    ) is
        l_source_system varchar2(60) := ie_mfcs_payload.source_system(p_payload);
        l_source_style_ref varchar2(120) := ie_mfcs_payload.source_style_ref(p_payload);
        l_type varchar2(10) := ie_mfcs_payload.document_item_number_type(p_payload);
    begin
        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'ASSIGN_SUPPLIED_START',
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_message => 'Recording caller-supplied MFCS item numbers; no reservation needed.',
            p_detail_payload => '{"sourceSystem":"' || ie_mfcs_event.escape_json(l_source_system)
                || '","sourceStyleRef":"' || ie_mfcs_event.escape_json(l_source_style_ref)
                || '","itemNumberType":"' || ie_mfcs_event.escape_json(l_type)
                || '","mfcsStyleNo":"' || ie_mfcs_event.escape_json(p_style_no) || '"}'
        );

        ie_mfcs_request.save_generated_identifier(
            p_action_request_id => p_action_request_id,
            p_source_system => l_source_system,
            p_source_style_ref => l_source_style_ref,
            p_mfcs_style_no => p_style_no
        );

        for v in ie_mfcs_payload.c_size_curve(p_payload) loop
            ie_mfcs_request.save_generated_identifier(
                p_action_request_id => p_action_request_id,
                p_source_system => l_source_system,
                p_source_style_ref => l_source_style_ref,
                p_mfcs_style_no => p_style_no,
                p_source_variant_ref => v.source_variant_ref,
                p_mfcs_sku_no => v.item_number,
                p_sku_size => v.sku_size,
                p_sku_width => v.sku_width
            );
        end loop;

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'ASSIGN_SUPPLIED_COMPLETE',
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_message => 'Caller-supplied MFCS item numbers recorded.',
            p_detail_payload => '{"mfcsStyleNo":"' || ie_mfcs_event.escape_json(p_style_no) || '"}'
        );
    end;

    procedure reserve_item_numbers_chunked(
        p_action_request_id in varchar2,
        p_user_id           in varchar2
    ) is
        l_payload clob := request_payload(p_action_request_id);
        l_source_system varchar2(60) := ie_mfcs_payload.source_system(l_payload);
        l_source_style_ref varchar2(120) := ie_mfcs_payload.source_style_ref(l_payload);
        l_request_payload clob;
        l_response clob;
        l_style_no varchar2(30);
        l_sku_no varchar2(30);
        l_days number := to_number(ie_mfcs_config.get_config('MFCS_ITEM_NUMBER_RESERVATION_DAYS_UNTIL_EXPIRY', '14'));
    begin
        l_request_payload := '{"itemNumberType":"ITEM","quantity":1,"daysUntilExpiry":' || l_days || '}';

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'RESERVE_CHUNK_START',
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_message => 'Starting chunked item-number reservation.',
            p_detail_payload => '{"sourceSystem":"' || ie_mfcs_event.escape_json(l_source_system)
                || '","sourceStyleRef":"' || ie_mfcs_event.escape_json(l_source_style_ref)
                || '","daysUntilExpiry":' || l_days || '}'
        );

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'RESERVE_STYLE_START',
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_message => 'Reserving MFCS item number for style.'
        );

        l_response := ie_mfcs_client.call_service(
            p_action_request_id => p_action_request_id,
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_http_method => 'POST',
            p_endpoint_key => 'ENDPOINT.ITEM_NUMBERS_MANAGE',
            p_request_payload => l_request_payload,
            p_user_id => p_user_id
        );

        l_style_no := first_reserved_item(l_response);

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'RESERVE_STYLE_SUCCEEDED',
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_message => 'Reserved MFCS style item number.',
            p_detail_payload => '{"mfcsStyleNo":"' || ie_mfcs_event.escape_json(l_style_no) || '"}'
        );

        ie_mfcs_request.save_generated_identifier(
            p_action_request_id => p_action_request_id,
            p_source_system => l_source_system,
            p_source_style_ref => l_source_style_ref,
            p_mfcs_style_no => l_style_no
        );

        for v in ie_mfcs_payload.c_size_curve(l_payload) loop
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'RESERVE_SKU_START',
                p_step_code => 'RESERVE_ITEM_NUMBERS',
                p_message => 'Reserving MFCS item number for SKU.',
                p_detail_payload => '{"sourceVariantRef":"' || ie_mfcs_event.escape_json(v.source_variant_ref)
                    || '","skuSize":"' || ie_mfcs_event.escape_json(v.sku_size)
                    || '","skuWidth":"' || ie_mfcs_event.escape_json(v.sku_width) || '"}'
            );

            l_response := ie_mfcs_client.call_service(
                p_action_request_id => p_action_request_id,
                p_step_code => 'RESERVE_ITEM_NUMBERS',
                p_http_method => 'POST',
                p_endpoint_key => 'ENDPOINT.ITEM_NUMBERS_MANAGE',
                p_request_payload => l_request_payload,
                p_user_id => p_user_id
            );

            l_sku_no := first_reserved_item(l_response);

            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'RESERVE_SKU_SUCCEEDED',
                p_step_code => 'RESERVE_ITEM_NUMBERS',
                p_message => 'Reserved MFCS SKU item number.',
                p_detail_payload => '{"sourceVariantRef":"' || ie_mfcs_event.escape_json(v.source_variant_ref)
                    || '","mfcsSkuNo":"' || ie_mfcs_event.escape_json(l_sku_no)
                    || '","mfcsStyleNo":"' || ie_mfcs_event.escape_json(l_style_no) || '"}'
            );

            ie_mfcs_request.save_generated_identifier(
                p_action_request_id => p_action_request_id,
                p_source_system => l_source_system,
                p_source_style_ref => l_source_style_ref,
                p_mfcs_style_no => l_style_no,
                p_source_variant_ref => v.source_variant_ref,
                p_mfcs_sku_no => l_sku_no,
                p_sku_size => v.sku_size,
                p_sku_width => v.sku_width
            );
        end loop;

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'RESERVE_CHUNK_COMPLETE',
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_message => 'Chunked item-number reservation completed.',
            p_detail_payload => '{"mfcsStyleNo":"' || ie_mfcs_event.escape_json(l_style_no) || '"}'
        );
    end;

    -- One reserve call for the whole style: the style's number plus one per
    -- child, in a single request. Resolution goes through resolve_step and
    -- payload_for_step rather than naming the endpoint here, so this path cannot
    -- drift from what the step graph says the step is.
    procedure reserve_item_numbers_bulk(
        p_action_request_id in varchar2,
        p_user_id           in varchar2
    ) is
        l_resolution t_step_resolution :=
            resolve_step('RESERVE_ITEM_NUMBERS', operation_name(p_action_request_id));
        l_response clob;
    begin
        l_response := ie_mfcs_client.call_service(
            p_action_request_id => p_action_request_id,
            p_step_code => 'RESERVE_ITEM_NUMBERS',
            p_http_method => l_resolution.http_method,
            p_endpoint_key => l_resolution.endpoint_key,
            p_request_payload => payload_for_step(p_action_request_id, 'RESERVE_ITEM_NUMBERS'),
            p_user_id => p_user_id
        );
        persist_item_numbers(p_action_request_id, l_response);
    end;

    -- Where this style's item numbers come from. One question, one place.
    --
    -- There are three answers and they used to be decided in three: the document
    -- inside the chunked reserve, the chunk size in the step loop, and the bulk
    -- reserve nowhere at all - it was whatever happened when neither of the other
    -- two matched. That left a trap: because "the caller supplied them" was
    -- reachable only through the chunk-size branch, changing
    -- MFCS_ITEM_NUMBER_RESERVATION_CHUNK_SIZE away from 1 would have silently
    -- reserved numbers for a document that had brought its own.
    --
    -- The payload is read once here and the branch is made on it. Whether the
    -- caller chose the numbers is a property of the request; how many numbers a
    -- reservation asks for at a time is a property of this deployment. Both are
    -- answered before anything is sent.
    procedure assign_item_numbers(
        p_action_request_id in varchar2,
        p_user_id           in varchar2
    ) is
        l_payload clob := request_payload(p_action_request_id);
        l_supplied_style varchar2(30) := ie_mfcs_payload.document_item_number(l_payload);
        l_chunk_size number :=
            to_number(ie_mfcs_config.get_config('MFCS_ITEM_NUMBER_RESERVATION_CHUNK_SIZE', '1'));
    begin
        if l_supplied_style is not null then
            -- Nothing to ask MFCS for. The numbers still land in IE_MFCS_MAP_ENTITY by the
            -- same call the reserve paths use, so no mapper downstream knows or
            -- cares which of these three branches ran.
            assign_supplied_item_numbers(p_action_request_id, l_payload, l_supplied_style);
        elsif l_chunk_size = 1 then
            reserve_item_numbers_chunked(p_action_request_id, p_user_id);
        else
            reserve_item_numbers_bulk(p_action_request_id, p_user_id);
        end if;
    end;

    procedure persist_po_number(
        p_action_request_id in varchar2,
        p_response          in clob
    ) is
        l_payload clob := request_payload(p_action_request_id);
        l_order_no varchar2(30);
    begin
        select coalesce(
                   json_value(p_response, '$.ORDER_NO' returning varchar2(30) null on error),
                   json_value(p_response, '$.orderNumbers[0].orderNo' returning varchar2(30) null on error)
               )
          into l_order_no
          from dual;

        ie_mfcs_request.save_generated_identifier(
            p_action_request_id => p_action_request_id,
            p_source_system => ie_mfcs_payload.source_system(l_payload),
            p_source_style_ref => ie_mfcs_payload.source_style_ref(l_payload),
            p_mfcs_style_no => null,
            p_source_order_ref => ie_mfcs_payload.source_order_ref(l_payload),
            p_mfcs_order_no => l_order_no
        );
    end;

    function payload_for_step(
        p_action_request_id in varchar2,
        p_step_code in varchar2
    ) return clob is
        l_mapper varchar2(80) :=
            resolve_step(p_step_code, operation_name(p_action_request_id)).mapper_name;
    begin
        if l_mapper is null then
            return '{"step":"' || p_step_code || '"}';
        end if;
        return ie_mfcs_payload.build_request(p_action_request_id, l_mapper);
    end;

    -- Whether the operation writes to a style that already exists in MFCS.
    --
    -- Order operations belong here as much as MODIFY_STYLE does: they carry the full
    -- style write set, so their item steps have to resolve to the update services.
    -- CREATE_ALL does not, because it creates the style in the same request.
    function targets_existing_style(p_operation in varchar2) return boolean is
    begin
        return p_operation in ('MODIFY_STYLE', 'CREATE_ORDER', 'MODIFY_ORDER');
    end;

    function resolve_step(p_step_code in varchar2, p_operation in varchar2) return t_step_resolution is
        l_r t_step_resolution;
        l_existing boolean := targets_existing_style(p_operation);

        procedure def(p_endpoint in varchar2, p_method in varchar2, p_mapper in varchar2) is
        begin
            l_r.endpoint_key := p_endpoint;
            l_r.http_method := p_method;
            l_r.mapper_name := p_mapper;
        end;
    begin
        case p_step_code
            when 'ENSURE_STYLE_SKUS' then
                null;  -- Local: handled inline; which calls it makes depends on the tenant.
            when 'SYNC_ORDER_LINES' then
                null;  -- Local: handled inline; reads the order, then updates/creates/cancels lines.
            when 'RESERVE_ITEM_NUMBERS' then
                def('ENDPOINT.ITEM_NUMBERS_MANAGE', 'POST', 'build_item_number_request');
            when 'CREATE_PARENT_ITEM_HIERARCHY' then
                def('ENDPOINT.ITEMS_CREATE', 'POST', 'build_parent_item_create_request');
            when 'CREATE_CHILD_ITEM_HIERARCHY' then
                def('ENDPOINT.ITEMS_CREATE', 'POST', 'build_child_item_create_request');
            when 'CREATE_ITEM_HIERARCHY' then
                if l_existing then
                    def('ENDPOINT.ITEMS_UPDATE', 'PUT', 'build_item_create_request');
                else
                    def('ENDPOINT.ITEMS_CREATE', 'POST', 'build_item_create_request');
                end if;
            when 'CREATE_PARENT_ITEM_SOURCING' then
                def('ENDPOINT.ITEM_SOURCING_CREATE', 'POST', 'build_parent_item_sourcing_request');
            when 'CREATE_ITEM_SOURCING' then
                if l_existing then
                    def('ENDPOINT.ITEM_SOURCING_UPDATE', 'PUT', 'build_item_sourcing_request');
                else
                    def('ENDPOINT.ITEM_SOURCING_CREATE', 'POST', 'build_item_sourcing_request');
                end if;
            when 'CREATE_ITEM_COUNTRIES_OF_MANUFACTURE' then
                -- Re-creating one is not a no-op, it is an error: "This
                -- item/supplier/manufacturing country already exists ...
                -- CORESVC_ITEM.PROCESS_ISMC". The update service takes the same body.
                if l_existing then
                    def('ENDPOINT.ITEM_COUNTRIES_OF_MANUFACTURE_UPDATE', 'PUT', 'build_item_country_of_manufacture_request');
                else
                    def('ENDPOINT.ITEM_COUNTRIES_OF_MANUFACTURE_CREATE', 'POST', 'build_item_country_of_manufacture_request');
                end if;
            when 'CREATE_REFERENCE_ITEMS' then
                -- Same endpoint as everything else at item level: a barcode is an
                -- item, not a separate resource. Update on an existing style for
                -- the same reason country of manufacture uses it - the write set
                -- is resent whole, and re-creating a row that exists is an error
                -- rather than a no-op. The update path here is not yet proven live.
                if l_existing then
                    def('ENDPOINT.ITEMS_UPDATE', 'PUT', 'build_reference_item_request');
                else
                    def('ENDPOINT.ITEMS_CREATE', 'POST', 'build_reference_item_request');
                end if;
            when 'CREATE_ITEM_UDAS' then
                if l_existing then
                    def('ENDPOINT.ITEM_UDAS_UPDATE', 'PUT', 'build_item_uda_request');
                else
                    def('ENDPOINT.ITEM_UDAS_CREATE', 'POST', 'build_item_uda_request');
                end if;
            when 'CREATE_ITEM_SEASONS' then
                def('ENDPOINT.ITEM_SEASONS_CREATE', 'POST', 'build_item_season_request');
            when 'CREATE_ITEM_IMAGES' then
                if l_existing then
                    def('ENDPOINT.ITEM_IMAGES_UPDATE', 'PUT', 'build_item_image_request');
                else
                    def('ENDPOINT.ITEM_IMAGES_CREATE', 'POST', 'build_item_image_request');
                end if;
            when 'CREATE_ITEM_HTS' then
                if l_existing then
                    def('ENDPOINT.ITEM_HTS_UPDATE', 'PUT', 'build_item_hts_request');
                else
                    def('ENDPOINT.ITEM_HTS_CREATE', 'POST', 'build_item_hts_request');
                end if;
            when 'CREATE_ITEM_LOCATIONS' then
                if l_existing then
                    def('ENDPOINT.ITEM_LOCATIONS_UPDATE', 'PUT', 'build_item_location_request');
                else
                    def('ENDPOINT.ITEM_LOCATIONS_CREATE', 'POST', 'build_item_location_request');
                end if;
            when 'APPROVE_ITEMS' then
                def('ENDPOINT.ITEM_APPROVE', 'PUT', 'build_item_approval_request');
            when 'APPLY_INITIAL_RETAIL' then
                def('ENDPOINT.INITIAL_RETAIL', 'POST', 'build_initial_retail_request');
            when 'RESERVE_ORDER_NUMBER' then
                def('ENDPOINT.PO_PREISSUED_CREATE', 'POST', 'build_po_number_request');
            when 'CREATE_PURCHASE_ORDER' then
                if p_operation = 'MODIFY_ORDER' then
                    def('ENDPOINT.PURCHASE_ORDERS_UPDATE', 'PUT', 'build_purchase_order_request');
                else
                    def('ENDPOINT.PURCHASE_ORDERS_CREATE', 'POST', 'build_purchase_order_request');
                end if;
            else
                null;  -- Unknown step: local by construction, nothing to send.
        end case;
        return l_r;
    end;

    -- json_object_t.get_boolean returns NULL for an absent key, and NULL in a PL/SQL
    -- condition is not false - "if not x" simply does nothing. Every branch below
    -- turns on one of these, so the absent case is made explicit.
    function is_true(p_value in boolean) return boolean is
    begin
        return p_value is not null and p_value;
    end;

    -- Records the SKU behind every colour/size combination the request names, as the
    -- tenant currently reports it.
    --
    -- The order builders resolve a SKU through ie_mfcs_map_entity when the document does not
    -- carry one, and a style created by an earlier request - or by somebody else
    -- entirely - leaves no row behind. Reading the mapping out of the gap analysis
    -- costs nothing extra: it has just been fetched.
    procedure record_resolved_skus(
        p_action_request_id in varchar2,
        p_style             in varchar2,
        p_gap               in json_object_t
    ) is
        l_payload clob := request_payload(p_action_request_id);
        l_source_system varchar2(60) := ie_mfcs_payload.source_system(l_payload);
        l_source_style_ref varchar2(120) := ie_mfcs_payload.source_style_ref(l_payload);
        l_required json_array_t := p_gap.get_array('required');
        l_entry json_object_t;
        l_size varchar2(60);
        l_sku varchar2(30);
        l_source_variant_ref varchar2(120);
        l_sku_width varchar2(60);
        l_recorded pls_integer := 0;
    begin
        if l_required is null then
            return;
        end if;

        for i in 0 .. l_required.get_size - 1 loop
            l_entry := treat(l_required.get(i) as json_object_t);
            l_sku := l_entry.get_string('sku');
            l_size := l_entry.get_string('size');

            if l_sku is not null then
                -- Join back to the size-curve row so the SKU is filed under the same
                -- source reference the rest of the request uses. Width is not part of
                -- the diff pair, so a size that appears twice with different widths
                -- resolves to the same SKU; take the first and let the mapping stand.
                l_source_variant_ref := null;
                l_sku_width := null;
                for v in ie_mfcs_payload.c_size_curve(l_payload) loop
                    if v.sku_size = l_size then
                        l_source_variant_ref := v.source_variant_ref;
                        l_sku_width := v.sku_width;
                        exit;
                    end if;
                end loop;

                if l_source_variant_ref is not null then
                    ie_mfcs_request.save_generated_identifier(
                        p_action_request_id => p_action_request_id,
                        p_source_system => l_source_system,
                        p_source_style_ref => l_source_style_ref,
                        p_mfcs_style_no => p_style,
                        p_source_variant_ref => l_source_variant_ref,
                        p_mfcs_sku_no => l_sku,
                        p_sku_size => l_size,
                        p_sku_width => l_sku_width
                    );
                    l_recorded := l_recorded + 1;
                end if;
            end if;
        end loop;

        if l_recorded > 0 then
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'SKU_MAPPING_RECORDED',
                p_step_code => 'ENSURE_STYLE_SKUS',
                p_message => 'Recorded the SKU behind each requested combination.',
                p_detail_payload => '{"mfcsStyleNo":"' || ie_mfcs_event.escape_json(p_style)
                    || '","skuCount":' || l_recorded || '}'
            );
        end if;
    end;

    -- Creates the children a style is missing: reserve a number for each, create
    -- them under the parent, give them sourcing and a country of manufacture, and
    -- approve them.
    --
    -- The order is not negotiable. MFCS will not approve an item that has no
    -- sourcing, and it will not accept sourcing for an item that does not exist yet.
    procedure generate_missing_skus(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_style             in varchar2,
        p_colour            in varchar2,
        p_sizes             in varchar2,
        p_gap               in json_object_t,
        p_user_id           in varchar2
    ) is
        l_payload clob := request_payload(p_action_request_id);
        l_attrs json_object_t := json_object_t.parse(ie_mfcs_sku.style_attributes(p_style));
        l_missing json_array_t := p_gap.get_array('missing');
        l_entry json_object_t;
        l_plan ie_mfcs_payload.t_child_plan;
        l_child_count pls_integer := 0;
        l_unmapped varchar2(1000);
        l_created varchar2(2000);
        l_response clob;
        l_item varchar2(30);
        l_size varchar2(60);
        l_source_variant_ref varchar2(120);
        l_sku_width varchar2(60);
        l_days number :=
            to_number(ie_mfcs_config.get_config('MFCS_ITEM_NUMBER_RESERVATION_DAYS_UNTIL_EXPIRY', '14'));
        l_retries number :=
            to_number(ie_mfcs_config.get_config('MFCS_SKU_VERIFY_RETRY_COUNT', '6'));
        l_sleep number :=
            to_number(ie_mfcs_config.get_config('MFCS_SKU_VERIFY_RETRY_SLEEP_SECONDS', '5'));
        l_verify json_object_t;
        l_verified boolean := false;
    begin
        -- A child has to join its parent's merchandise hierarchy. Nothing in this
        -- layer is entitled to guess one, so an unreadable parent stops the work
        -- before any item number is burned.
        if not is_true(l_attrs.get_boolean('available')) then
            raise_application_error(-20962,
                'Cannot create children for style ' || p_style || ': its own attributes '
                || 'could not be read (' || l_attrs.get_string('message')
                || '). A child inherits the parent hierarchy, so it cannot be guessed.');
        end if;

        -- The itemDetail JSON becomes a typed plan here, in one place; from this
        -- point on a misspelled attribute is a compile error, not a silent null.
        l_plan.style := p_style;
        l_plan.dept := l_attrs.get_number('dept');
        l_plan.class := l_attrs.get_number('class');
        l_plan.subclass := l_attrs.get_number('subclass');
        l_plan.original_retail := l_attrs.get_number('originalRetail');
        l_plan.cost_zone_group_id := l_attrs.get_number('costZoneGroupId');
        l_plan.item_description := l_attrs.get_string('itemDescription');
        l_plan.short_description := l_attrs.get_string('shortDescription');
        l_plan.standard_uom := l_attrs.get_string('standardUom');
        l_plan.store_order_multiple := l_attrs.get_string('storeOrderMultiple');
        l_plan.supplier := l_attrs.get_number('supplier');
        l_plan.unit_cost := l_attrs.get_number('unitCost');
        l_plan.origin_country := l_attrs.get_string('originCountry');

        for i in 0 .. l_missing.get_size - 1 loop
            l_entry := treat(l_missing.get(i) as json_object_t);
            if not is_true(l_entry.get_boolean('mappingFound')) then
                l_unmapped := l_unmapped
                    || case when l_unmapped is not null then ', ' end
                    || l_entry.get_string('size');
            end if;
        end loop;

        -- A null size would go out as a null differentiator, and the gap analysis
        -- would report the same combination missing on every subsequent run. Since
        -- sizes are now the tenant's own differentiator IDs rather than display
        -- values needing a MAP.SIZE entry, this only fires on a genuinely empty
        -- size rather than on a missing mapping.
        if l_unmapped is not null then
            raise_application_error(-20963,
                'Style ' || p_style || ' needs sizes that resolved to no differentiator: '
                || substr(l_unmapped, 1, 300) || '.');
        end if;

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'SKU_GENERATION_START',
            p_step_code => p_step_code,
            p_message => 'Creating the children this style is missing.',
            p_detail_payload => '{"mfcsStyleNo":"' || ie_mfcs_event.escape_json(p_style)
                || '","colour":"' || ie_mfcs_event.escape_json(p_colour)
                || '","missingCount":' || l_missing.get_size || '}'
        );

        -- One reservation per child, matching how the create flow reserves numbers.
        for i in 0 .. l_missing.get_size - 1 loop
            l_entry := treat(l_missing.get(i) as json_object_t);
            l_size := l_entry.get_string('size');

            l_source_variant_ref := null;
            l_sku_width := null;
            for v in ie_mfcs_payload.c_size_curve(l_payload) loop
                if v.sku_size = l_size then
                    l_source_variant_ref := v.source_variant_ref;
                    l_sku_width := v.sku_width;
                    exit;
                end if;
            end loop;

            l_response := ie_mfcs_client.call_service(
                p_action_request_id => p_action_request_id,
                p_step_code => p_step_code,
                p_http_method => 'POST',
                p_endpoint_key => 'ENDPOINT.ITEM_NUMBERS_MANAGE',
                p_request_payload =>
                    '{"itemNumberType":"ITEM","quantity":1,"daysUntilExpiry":' || l_days || '}',
                p_user_id => p_user_id
            );
            l_item := first_reserved_item(l_response);

            l_child_count := l_child_count + 1;
            l_plan.children(l_child_count).item := l_item;
            l_plan.children(l_child_count).sku_size := l_size;
            l_plan.children(l_child_count).size_diff := l_entry.get_string('sizeDiff');
            l_plan.children(l_child_count).colour_diff := l_entry.get_string('colourDiff');
            l_plan.children(l_child_count).source_variant_ref := l_source_variant_ref;
            l_plan.children(l_child_count).sku_width := l_sku_width;

            l_created := l_created
                || case when l_created is not null then ', ' end
                || l_item || ' (' || l_entry.get_string('colourDiff')
                || '/' || l_entry.get_string('sizeDiff') || ')';

            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'SKU_NUMBER_RESERVED',
                p_step_code => p_step_code,
                p_message => 'Reserved an item number for a missing combination.',
                p_detail_payload => '{"mfcsSkuNo":"' || ie_mfcs_event.escape_json(l_item)
                    || '","size":"' || ie_mfcs_event.escape_json(l_size)
                    || '","sizeDiff":"' || ie_mfcs_event.escape_json(l_entry.get_string('sizeDiff'))
                    || '","colourDiff":"' || ie_mfcs_event.escape_json(l_entry.get_string('colourDiff')) || '"}'
            );
        end loop;

        l_response := ie_mfcs_client.call_service(
            p_action_request_id => p_action_request_id,
            p_step_code => p_step_code,
            p_http_method => 'POST',
            p_endpoint_key => 'ENDPOINT.ITEMS_CREATE',
            p_request_payload => ie_mfcs_payload.generated_child_create_request(p_action_request_id, l_plan),
            p_user_id => p_user_id
        );

        l_response := ie_mfcs_client.call_service(
            p_action_request_id => p_action_request_id,
            p_step_code => p_step_code,
            p_http_method => 'POST',
            p_endpoint_key => 'ENDPOINT.ITEM_SOURCING_CREATE',
            p_request_payload => ie_mfcs_payload.generated_child_sourcing_request(p_action_request_id, l_plan),
            p_user_id => p_user_id
        );

        l_response := ie_mfcs_client.call_service(
            p_action_request_id => p_action_request_id,
            p_step_code => p_step_code,
            p_http_method => 'POST',
            p_endpoint_key => 'ENDPOINT.ITEM_COUNTRIES_OF_MANUFACTURE_CREATE',
            p_request_payload => ie_mfcs_payload.generated_child_com_request(p_action_request_id, l_plan),
            p_user_id => p_user_id
        );

        l_response := ie_mfcs_client.call_service(
            p_action_request_id => p_action_request_id,
            p_step_code => p_step_code,
            p_http_method => 'PUT',
            p_endpoint_key => 'ENDPOINT.ITEM_APPROVE',
            p_request_payload => ie_mfcs_payload.generated_child_approval_request(p_action_request_id, l_plan),
            p_user_id => p_user_id
        );

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'SKU_GENERATION_SENT',
            p_step_code => p_step_code,
            p_message => 'Created, sourced and approved the missing children.',
            p_detail_payload => '{"mfcsStyleNo":"' || ie_mfcs_event.escape_json(p_style)
                || '","children":"' || ie_mfcs_event.escape_json(substr(l_created, 1, 900)) || '"}'
        );

        -- Read the style back rather than trusting four HTTP 200s. This is the whole
        -- reason the step exists: MFCS answers an item write that changes nothing
        -- with SUCCESS, so the only evidence that the children now exist is finding
        -- them. Newly approved items take a moment to become readable, hence retries.
        for i in 1 .. greatest(1, l_retries) loop
            l_verify := json_object_t.parse(ie_mfcs_sku.resolve_gap(p_style, p_colour, p_sizes));
            l_verified := is_true(l_verify.get_boolean('resolved'))
                          and is_true(l_verify.get_boolean('complete'));
            exit when l_verified;

            if i < greatest(1, l_retries) then
                ie_mfcs_event.log_event(
                    p_action_request_id => p_action_request_id,
                    p_event_phase => 'SKU_VERIFY_RETRY_WAIT',
                    p_step_code => p_step_code,
                    p_event_level => 'WARN',
                    p_message => 'The new children are not readable yet; waiting before re-reading.',
                    p_detail_payload => '{"retryNumber":' || i
                        || ',"maxRetries":' || greatest(1, l_retries)
                        || ',"sleepSeconds":' || l_sleep || '}'
                );
                dbms_session.sleep(l_sleep);
            end if;
        end loop;

        if not l_verified then
            raise_application_error(-20965,
                'Created children for style ' || p_style || ' but reading the style back still '
                || 'reports ' || nvl(to_char(l_verify.get_number('missingCount')), 'some')
                || ' combination(s) missing. MFCS accepted the calls without applying them.');
        end if;

        record_resolved_skus(p_action_request_id, p_style, l_verify);

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'SKU_GENERATION_VERIFIED',
            p_step_code => p_step_code,
            p_message => 'Style ' || p_style || ' now carries every requested combination.',
            p_detail_payload => '{"mfcsStyleNo":"' || ie_mfcs_event.escape_json(p_style)
                || '","createdCount":' || l_child_count || '}'
        );
    end;

    -- Confirms the style carries every colour/size combination the request names,
    -- and creates the ones it does not.
    --
    -- Why this is one step rather than five: which children are missing is only
    -- known after reading the tenant, so a step graph fixed at request registration
    -- cannot express it. Doing the work inline also makes the step re-entrant for
    -- nothing - a resume re-reads the style, sees whatever a failed attempt managed
    -- to create, and creates only the remainder. Stored-payload steps could not,
    -- because they would replay item numbers that had already been used.
    --
    -- With generation switched off the step still runs, and still stops the request.
    -- That is deliberate: MFCS accepts a diff change on an existing SKU, reports
    -- SUCCESS and leaves the item alone, so an unchecked colour change would
    -- complete having achieved nothing at all.
    procedure ensure_style_skus(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_user_id           in varchar2
    ) is
        l_payload clob := request_payload(p_action_request_id);
        l_style varchar2(30);
        l_colour varchar2(120);
        l_sizes varchar2(4000);
        l_gap json_object_t;
        l_missing json_array_t;
        l_entry json_object_t;
        l_detail varchar2(2000);
        l_generate boolean :=
            ie_mfcs_config.get_config('FEATURE_GENERATE_MISSING_SKUS_YN', 'Y') = 'Y';
    begin
        select style_no into l_style
          from ie_mfcs_prd_request where action_request_id = p_action_request_id;

        l_colour := ie_mfcs_payload.string_value(l_payload, 'COLOUR');

        for v in ie_mfcs_payload.c_size_curve(l_payload) loop
            l_sizes := l_sizes || case when l_sizes is not null then ':' end || v.sku_size;
        end loop;

        if l_style is null then
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'SUCCEEDED');
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'ENSURE_SKUS_SKIPPED',
                p_step_code => p_step_code,
                p_message => 'No style on the request to check against.');
            return;
        end if;

        l_gap := json_object_t.parse(ie_mfcs_sku.resolve_gap(l_style, l_colour, l_sizes));

        if not is_true(l_gap.get_boolean('resolved')) then
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'FAILED',
                'SKU_LOOKUP_FAILED', substr(l_gap.get_string('message'), 1, 400));
            raise_application_error(-20960,
                'Could not read the SKUs of style ' || l_style || ': ' || l_gap.get_string('message'));
        end if;

        if is_true(l_gap.get_boolean('complete')) then
            record_resolved_skus(p_action_request_id, l_style, l_gap);
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'SUCCEEDED');
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'ENSURE_SKUS_COMPLETE',
                p_step_code => p_step_code,
                p_message => 'Style ' || l_style || ' already carries every requested combination.');
            return;
        end if;

        if l_generate then
            generate_missing_skus(
                p_action_request_id => p_action_request_id,
                p_step_code => p_step_code,
                p_style => l_style,
                p_colour => l_colour,
                p_sizes => l_sizes,
                p_gap => l_gap,
                p_user_id => p_user_id
            );
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'SUCCEEDED');
            return;
        end if;

        l_missing := l_gap.get_array('missing');
        for i in 0 .. l_missing.get_size - 1 loop
            l_entry := treat(l_missing.get(i) as json_object_t);
            l_detail := l_detail
                || case when l_detail is not null then ', ' end
                || l_gap.get_string('colourDiff') || '/'
                || nvl(l_entry.get_string('sizeDiff'),
                       '(unmapped size ' || l_entry.get_string('size') || ')');
        end loop;

        ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'FAILED', 'SKUS_MISSING',
            substr('Style ' || l_style || ' has no SKU for: ' || l_detail
                || '. A colour or size the style does not already carry needs new child items, '
                || 'and FEATURE_GENERATE_MISSING_SKUS_YN is off.',
                1, 1000));
        raise_application_error(-20961,
            'Style ' || l_style || ' is missing ' || l_gap.get_number('missingCount')
            || ' SKU(s): ' || substr(l_detail, 1, 300));
    end;

    -- Brings a purchase order's detail lines in line with the document.
    --
    -- purchaseOrders/update answers SUCCESS while ignoring its details array on
    -- this tenant - proven live with replaced items and again with a plain
    -- quantity change. Lines change through purchaseOrder/details/create|update,
    -- and a line stops through details/update with cancelInd and a cancel code.
    --
    -- Like ENSURE_STYLE_SKUS this runs inline, because what it sends depends on
    -- what the order currently holds: lines the document names are updated or
    -- created, and lines of THIS style that the document no longer names are
    -- cancelled (a colour switch leaves one behind). Lines of other styles are
    -- never touched - the document speaks for its own style only.
    procedure sync_order_lines(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_user_id           in varchar2
    ) is
        type t_qty_map is table of number index by varchar2(30);
        l_payload clob := request_payload(p_action_request_id);
        l_order_no varchar2(30);
        l_style varchar2(30);
        l_status number;
        l_body clob;
        l_orders json_array_t;
        l_order json_object_t;
        l_details json_array_t;
        l_line json_object_t;
        l_existing t_qty_map;
        l_desired t_qty_map;
        l_children t_qty_map;
        l_skus json_object_t;
        l_sku_arr json_array_t;
        l_item varchar2(30);
        l_plan ie_mfcs_payload.t_order_line_plan;
        l_n pls_integer;
        l_response clob;
        l_absent_action varchar2(10) :=
            ie_mfcs_config.get_config('MFCS_ORDER_LINE_ABSENT_ACTION', 'CANCEL');
        l_retries number := to_number(ie_mfcs_config.get_config('MFCS_ORDER_VERIFY_RETRY_COUNT', '12'));
        l_sleep number := to_number(ie_mfcs_config.get_config('MFCS_ORDER_VERIFY_RETRY_SLEEP_SECONDS', '10'));
        l_verified boolean;
        l_mismatch varchar2(1000);

        procedure read_order_lines is
        begin
            l_existing.delete;
            l_body := ie_mfcs_client.get_json(
                '/MerchIntegrations/services/procurement/order/' || l_order_no, l_status);
            if l_status not between 200 and 299 then
                raise_application_error(-20966,
                    'Could not read order ' || l_order_no || ' before syncing its lines (HTTP '
                    || l_status || ').');
            end if;
            l_orders := json_object_t.parse(l_body).get_array('items');
            if l_orders is null or l_orders.get_size = 0 then
                raise_application_error(-20966,
                    'Order ' || l_order_no || ' returned no rows; cannot sync lines against it.');
            end if;
            l_order := treat(l_orders.get(0) as json_object_t);
            l_details := l_order.get_array('orderDetail');
            if l_details is null then
                l_details := l_order.get_array('details');
            end if;
            for i in 0 .. nvl(l_details.get_size, 0) - 1 loop
                l_line := treat(l_details.get(i) as json_object_t);
                -- Read vocabulary: physicalQuantityOrdered, not quantityOrdered.
                l_existing(l_line.get_string('item')) :=
                    nvl(l_line.get_number('physicalQuantityOrdered'),
                        l_line.get_number('quantityOrdered'));
            end loop;
        end;
    begin
        select order_no, style_no into l_order_no, l_style
          from ie_mfcs_prd_request where action_request_id = p_action_request_id;

        if l_order_no is null then
            ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'SUCCEEDED');
            return;
        end if;

        -- What the document says the lines should be. SKUs resolve exactly the
        -- way the order mapper resolves them, through the same public function.
        for v in ie_mfcs_payload.c_size_curve(l_payload) loop
            l_item := ie_mfcs_payload.resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
            if l_item is not null then
                l_desired(l_item) := v.sku_qty;
            end if;
        end loop;

        read_order_lines;

        -- This style's children, from the tenant, so cancellation can be scoped
        -- to lines the document actually speaks for.
        l_skus := json_object_t.parse(ie_mfcs_sku.existing_skus(l_style));
        if l_skus.get_boolean('available') then
            l_sku_arr := l_skus.get_array('skus');
            for i in 0 .. l_sku_arr.get_size - 1 loop
                l_children(treat(l_sku_arr.get(i) as json_object_t).get_string('item')) := 1;
            end loop;
        end if;

        -- Order-level values for the line nodes, same sources as the order mapper.
        l_plan.order_no := l_order_no;
        l_plan.location := to_number(nvl(
            ie_mfcs_payload.virtual_location(ie_mfcs_payload.string_value(l_payload, 'DELIVERY_LOC')),
            ie_mfcs_config.get_config('MFCS_ORDER_DEFAULT_LOCATION', '19271')));
        l_plan.location_type := ie_mfcs_config.get_config('MFCS_ORDER_LOCATION_TYPE', 'W');
        l_plan.origin_country := ie_mfcs_payload.string_value(l_payload, 'ORIGIN_COUNTRY');
        l_plan.unit_cost := to_number(ie_mfcs_payload.string_value(l_payload, 'UNIT_COST'));
        l_plan.supplier_pack_size := to_number(ie_mfcs_config.get_config('MFCS_SUPPLIER_PACK_SIZE', '1'));
        l_plan.earliest_ship_date := ie_mfcs_payload.string_value(l_payload, 'EARLIEST_SHIP_DATE');
        l_plan.latest_ship_date := ie_mfcs_payload.string_value(l_payload, 'LATEST_SHIP_DATE');

        l_item := l_desired.first;
        while l_item is not null loop
            if l_existing.exists(l_item) then
                l_n := l_plan.updates.count + 1;
                l_plan.updates(l_n).item := l_item;
                l_plan.updates(l_n).quantity := l_desired(l_item);
                l_plan.updates(l_n).prev_quantity := l_existing(l_item);
            else
                l_n := l_plan.creates.count + 1;
                l_plan.creates(l_n).item := l_item;
                l_plan.creates(l_n).quantity := l_desired(l_item);
            end if;
            l_item := l_desired.next(l_item);
        end loop;

        if l_absent_action = 'CANCEL' then
            l_item := l_existing.first;
            while l_item is not null loop
                if not l_desired.exists(l_item) and l_children.exists(l_item) then
                    l_n := l_plan.cancels.count + 1;
                    l_plan.cancels(l_n).item := l_item;
                    l_plan.cancels(l_n).quantity := l_existing(l_item);
                end if;
                l_item := l_existing.next(l_item);
            end loop;
        end if;

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'ORDER_LINES_PLAN',
            p_step_code => p_step_code,
            p_message => 'Order read; line changes decided.',
            p_detail_payload => '{"orderNo":"' || ie_mfcs_event.escape_json(l_order_no)
                || '","updates":' || l_plan.updates.count
                || ',"creates":' || l_plan.creates.count
                || ',"cancels":' || l_plan.cancels.count || '}'
        );

        if l_plan.updates.count > 0 then
            l_response := ie_mfcs_client.call_service(
                p_action_request_id => p_action_request_id,
                p_step_code => p_step_code,
                p_http_method => 'PUT',
                p_endpoint_key => 'ENDPOINT.PO_DETAILS_UPDATE',
                p_request_payload => ie_mfcs_payload.order_details_update_request(l_plan),
                p_user_id => p_user_id
            );
        end if;

        if l_plan.creates.count > 0 then
            l_response := ie_mfcs_client.call_service(
                p_action_request_id => p_action_request_id,
                p_step_code => p_step_code,
                p_http_method => 'POST',
                p_endpoint_key => 'ENDPOINT.PO_DETAILS_CREATE',
                p_request_payload => ie_mfcs_payload.order_details_create_request(l_plan),
                p_user_id => p_user_id
            );
        end if;

        if l_plan.cancels.count > 0 then
            l_response := ie_mfcs_client.call_service(
                p_action_request_id => p_action_request_id,
                p_step_code => p_step_code,
                p_http_method => 'PUT',
                p_endpoint_key => 'ENDPOINT.PO_DETAILS_UPDATE',
                p_request_payload => ie_mfcs_payload.order_details_cancel_request(l_plan),
                p_user_id => p_user_id
            );
        end if;

        -- Read back until every line the document names shows its quantity.
        -- Line changes take ~30 seconds to appear in the procurement read -
        -- far longer than the feed lag elsewhere - hence the long patience.
        for attempt in 1 .. greatest(1, l_retries) loop
            l_verified := true;
            l_mismatch := null;
            read_order_lines;
            -- Cancelled lines must read zero (or be gone). They are part of what
            -- the document asked for, so they are part of what read-back proves.
            for c in 1 .. l_plan.cancels.count loop
                if l_existing.exists(l_plan.cancels(c).item)
                   and l_existing(l_plan.cancels(c).item) <> 0 then
                    l_verified := false;
                    l_mismatch := l_mismatch
                        || case when l_mismatch is not null then ', ' end
                        || l_plan.cancels(c).item || ' expected cancelled, got '
                        || l_existing(l_plan.cancels(c).item);
                end if;
            end loop;
            l_item := l_desired.first;
            while l_item is not null loop
                if not l_existing.exists(l_item)
                   or l_existing(l_item) <> l_desired(l_item) then
                    l_verified := false;
                    l_mismatch := l_mismatch
                        || case when l_mismatch is not null then ', ' end
                        || l_item || ' expected ' || l_desired(l_item)
                        -- exists() guards the read: indexing an absent key raises
                        -- NO_DATA_FOUND, which cost this step its first live run.
                        || ' got ' || case when l_existing.exists(l_item)
                                          then to_char(l_existing(l_item))
                                          else 'absent' end;
                end if;
                l_item := l_desired.next(l_item);
            end loop;
            exit when l_verified;

            if attempt < greatest(1, l_retries) then
                ie_mfcs_event.log_event(
                    p_action_request_id => p_action_request_id,
                    p_event_phase => 'ORDER_LINES_VERIFY_WAIT',
                    p_step_code => p_step_code,
                    p_event_level => 'WARN',
                    p_message => 'Order lines not yet as requested; waiting before re-reading.',
                    p_detail_payload => '{"attempt":' || attempt
                        || ',"sleepSeconds":' || l_sleep
                        || ',"mismatch":"' || ie_mfcs_event.escape_json(substr(l_mismatch, 1, 400)) || '"}'
                );
                dbms_session.sleep(l_sleep);
            end if;
        end loop;

        if not l_verified then
            raise_application_error(-20967,
                'Order ' || l_order_no || ' lines still differ from the document after '
                || greatest(1, l_retries) || ' reads: ' || substr(l_mismatch, 1, 500)
                || '. MFCS accepted the line calls without applying them.');
        end if;

        ie_mfcs_step.set_step_status(p_action_request_id, p_step_code, 'SUCCEEDED');
        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'ORDER_LINES_VERIFIED',
            p_step_code => p_step_code,
            p_message => 'Order ' || l_order_no || ' now carries the document''s lines, read back and confirmed.'
        );
    end;

    procedure execute_request(
        p_action_request_id in varchar2
    ) is
        l_step varchar2(60);
        l_operation varchar2(30) := operation_name(p_action_request_id);
        l_payload clob := request_payload(p_action_request_id);
        l_user_id varchar2(120) := ie_mfcs_payload.user_id(l_payload);
        l_request_payload clob;
        l_response clob;
        l_resolution t_step_resolution;
        l_endpoint_key varchar2(200);
        l_method varchar2(10);
        l_recovery_status varchar2(30);
        l_started_at timestamp with time zone := systimestamp;
        l_budget_seconds number := to_number(ie_mfcs_config.get_config('INTERNAL_TIME_BUDGET_SECONDS', '240'));
        l_collection_size number;
    begin
        if l_operation = 'CREATE_ALL'
           and ie_mfcs_config.get_config('BATCH_WINDOW_ACTIVE_YN', 'N') = 'Y'
           and not any_succeeded(p_action_request_id) then
            ie_mfcs_request.set_request_status(
                p_action_request_id,
                'FAILED_NO_SIDE_EFFECT',
                '{"ACTION_REQUEST_ID":"' || p_action_request_id || '","STATUS":"FAILED_NO_SIDE_EFFECT","RETRYABLE":true,"COMPLETED_STEPS":[],"FAILED_STEP":null,"GENERATED_IDENTIFIERS":{},"ERRORS":[{"FIELD":"MFCS_BATCH_WINDOW","CODE":"MFCS_BATCH_WINDOW_ACTIVE","MESSAGE":"Required MFCS services are unavailable during the configured batch window."}]}'
            );
            return;
        end if;

        ie_mfcs_request.set_request_status(p_action_request_id, 'IN_PROGRESS');
        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'REQUEST_EXECUTE_START',
            p_message => 'MFCS orchestration started.',
            p_detail_payload => '{"operationName":"' || ie_mfcs_event.escape_json(l_operation)
                || '","userId":"' || ie_mfcs_event.escape_json(l_user_id)
                || '","budgetSeconds":' || l_budget_seconds || '}'
        );
        ie_mfcs_step.set_step_status(p_action_request_id, 'VALIDATE_REQUEST', 'SUCCEEDED');

        loop
            l_step := ie_mfcs_step.first_runnable_step(p_action_request_id);
            exit when l_step is null;

            if l_step = 'VALIDATE_REQUEST' then
                ie_mfcs_step.set_step_status(p_action_request_id, l_step, 'SUCCEEDED');
                continue;
            end if;

            if l_step = 'ENSURE_STYLE_SKUS' then
                ensure_style_skus(p_action_request_id, l_step, l_user_id);
                continue;
            end if;

            if l_step = 'SYNC_ORDER_LINES' then
                sync_order_lines(p_action_request_id, l_step, l_user_id);
                continue;
            end if;

            if (cast(systimestamp as date) - cast(l_started_at as date)) * 86400 >= l_budget_seconds then
                ie_mfcs_request.set_request_status(
                    p_action_request_id,
                    case when any_succeeded(p_action_request_id) then 'PARTIALLY_COMPLETED' else 'FAILED_NO_SIDE_EFFECT' end,
                    ie_mfcs_request.build_status_response(
                        p_action_request_id,
                        case when any_succeeded(p_action_request_id) then 'PARTIALLY_COMPLETED' else 'FAILED_NO_SIDE_EFFECT' end
                    )
                );
                return;
            end if;

            select step_status
              into l_recovery_status
              from ie_mfcs_prd_request_step
             where action_request_id = p_action_request_id
               and step_code = l_step;

            if l_recovery_status = 'OUTCOME_UNKNOWN' then
                l_recovery_status := ie_mfcs_recovery.resolve_step(p_action_request_id, l_step);
                if l_recovery_status = 'SUCCEEDED' then
                    continue;
                elsif l_recovery_status = 'MANUAL_REVIEW' then
                    return;
                end if;
            end if;

            l_resolution := resolve_step(l_step, l_operation);
            l_endpoint_key := l_resolution.endpoint_key;
            l_method := l_resolution.http_method;
            l_request_payload := payload_for_step(p_action_request_id, l_step);

            -- Asked here, against the payload as just built, and not later.
            --
            -- The mappers return a temporary CLOB, and both calls below this one
            -- commit. Reading that locator after a commit is the kind of thing
            -- that works almost every time: an intermittent run of
            -- CREATE_ITEM_SEASONS failures was traced to this guard answering
            -- null for a payload whose bytes were provably intact - the
            -- STEP_START journal recorded its 31 bytes moments earlier. Because
            -- the guard says `null on error`, a null does not raise; it just
            -- reads as "not empty", and the empty array goes to MFCS, which
            -- rejects it and leaves the request PARTIALLY_COMPLETED for a
            -- document that was never wrong.
            --
            -- One read, at the point the payload exists, removes the window.
            -- Null still means "no collectionSize key", which is the honest
            -- answer for the reserve payload and correctly does not skip.
            l_collection_size :=
                json_value(l_request_payload, '$.collectionSize' returning number null on error);

            ie_mfcs_step.set_step_status(p_action_request_id, l_step, 'IN_PROGRESS');
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'STEP_START',
                p_step_code => l_step,
                p_message => 'MFCS orchestration step started.',
                p_detail_payload => '{"endpointKey":"' || ie_mfcs_event.escape_json(l_endpoint_key)
                    || '","method":"' || ie_mfcs_event.escape_json(l_method)
                    || '","requestBytes":' || coalesce(to_char(dbms_lob.getlength(l_request_payload)), '0') || '}'
            );

            -- A step whose write set came out empty has nothing to say to the
            -- tenant, and saying it anyway is not harmless: items/create rejects
            -- an empty items array, which fails the step and leaves the request
            -- PARTIALLY_COMPLETED for a document that was never wrong.
            --
            -- This is how CREATE_REFERENCE_ITEMS stays genuinely optional. A
            -- document with no SKU_UPCS builds collectionSize 0, and the step
            -- succeeds without a call rather than being skipped from the graph -
            -- so the journal still shows it was considered.
            if l_collection_size = 0 then
                ie_mfcs_step.set_step_status(p_action_request_id, l_step, 'SUCCEEDED');
                ie_mfcs_event.log_event(
                    p_action_request_id => p_action_request_id,
                    p_event_phase => 'STEP_SUCCEEDED',
                    p_step_code => l_step,
                    p_message => 'Nothing to send: the document produced an empty write set.'
                );
                continue;
            end if;

            if l_step = 'RESERVE_ITEM_NUMBERS' then
                assign_item_numbers(p_action_request_id, l_user_id);
                ie_mfcs_step.set_step_status(p_action_request_id, l_step, 'SUCCEEDED');
                ie_mfcs_event.log_event(
                    p_action_request_id => p_action_request_id,
                    p_event_phase => 'STEP_SUCCEEDED',
                    p_step_code => l_step,
                    p_message => 'MFCS orchestration step succeeded.'
                );
                continue;
            end if;

            l_response := ie_mfcs_client.call_service(
                p_action_request_id => p_action_request_id,
                p_step_code => l_step,
                p_http_method => l_method,
                p_endpoint_key => l_endpoint_key,
                p_request_payload => l_request_payload,
                p_user_id => l_user_id
            );

            -- RESERVE_ITEM_NUMBERS never reaches here: assign_item_numbers owns
            -- that step in full, including its bulk branch's own persist.
            if l_step = 'RESERVE_ORDER_NUMBER' then
                persist_po_number(p_action_request_id, l_response);
            end if;

            ie_mfcs_step.set_step_status(p_action_request_id, l_step, 'SUCCEEDED');
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'STEP_SUCCEEDED',
                p_step_code => l_step,
                p_message => 'MFCS orchestration step succeeded.'
            );
        end loop;

        ie_mfcs_request.set_request_status(
            p_action_request_id,
            'COMPLETED',
            ie_mfcs_request.build_status_response(p_action_request_id, 'COMPLETED')
        );
        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'REQUEST_COMPLETED',
            p_message => 'MFCS orchestration completed.'
        );
    exception
        when ie_mfcs_client.e_outcome_unknown then
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'STEP_OUTCOME_UNKNOWN',
                p_step_code => l_step,
                p_event_level => 'WARN',
                p_message => substr(sqlerrm, 1, 1000),
                p_detail_payload => '{"sqlcode":' || sqlcode || '}'
            );
            ie_mfcs_step.set_step_status(p_action_request_id, l_step, 'OUTCOME_UNKNOWN', null, 'OUTCOME_UNKNOWN', sqlerrm);
            ie_mfcs_request.set_request_status(p_action_request_id, 'OUTCOME_UNKNOWN', ie_mfcs_request.build_status_response(p_action_request_id, 'OUTCOME_UNKNOWN'));
        when others then
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'STEP_EXCEPTION',
                p_step_code => l_step,
                p_event_level => 'ERROR',
                p_message => substr(sqlerrm, 1, 1000),
                p_detail_payload => '{"sqlcode":' || sqlcode || '}'
            );
            if l_step is not null then
                ie_mfcs_step.set_step_status(p_action_request_id, l_step, 'FAILED', null, to_char(sqlcode), sqlerrm);
            end if;

            if any_succeeded(p_action_request_id) then
                ie_mfcs_request.set_request_status(p_action_request_id, 'PARTIALLY_COMPLETED', ie_mfcs_request.build_status_response(p_action_request_id, 'PARTIALLY_COMPLETED'));
            else
                ie_mfcs_request.set_request_status(
                    p_action_request_id,
                    'FAILED_NO_SIDE_EFFECT',
                    '{"ACTION_REQUEST_ID":"' || p_action_request_id || '","STATUS":"FAILED_NO_SIDE_EFFECT","RETRYABLE":true,"COMPLETED_STEPS":[],"FAILED_STEP":"' || l_step || '","GENERATED_IDENTIFIERS":{},"ERRORS":[{"FIELD":"' || l_step || '","CODE":"' || sqlcode || '","MESSAGE":"' || replace(sqlerrm, '"', '\"') || '"}]}'
                );
            end if;
    end;

    procedure resume_request(
        p_action_request_id in varchar2
    ) is
    begin
        execute_request(p_action_request_id);
    end;
end ie_mfcs_orchestrator;
/

-- ==== 20_packages/11_ie_mfcs_preview.sql

-- Builds the MFCS call plan without sending anything.

create or replace package ie_mfcs_preview authid definer as
    -- Builds, but does not send, the full MFCS call plan for an Office payload.
    --
    -- Returns both halves of the picture in one response:
    --   INBOUND_PAYLOAD - the Office/PLM-shaped request as received by this layer
    --   MFCS_CALLS      - the ordered per-endpoint payloads the orchestrator would send
    --
    -- Nothing is sent to MFCS and no request survives the call: a throwaway
    -- PREVIEW- request is registered so the existing mappers can run against it,
    -- then removed. Reuses the orchestrator's own step graph and endpoint
    -- resolution, so a preview cannot drift from what execution would actually do.
    procedure preview_transaction(
        p_payload      in clob,
        o_http_status  out number,
        o_response     out clob
    );
end ie_mfcs_preview;
/

create or replace package body ie_mfcs_preview as

    procedure purge_preview(p_action_request_id in varchar2) is
    begin
        delete from ie_mfcs_log_event where action_request_id = p_action_request_id;
        delete from ie_mfcs_prd_step_attempt where action_request_id = p_action_request_id;
        delete from ie_mfcs_prd_request_step where action_request_id = p_action_request_id;
        delete from ie_mfcs_prd_request where action_request_id = p_action_request_id;
        commit;
    exception
        when others then
            null;
    end;

    -- Embed a built payload as real JSON where possible, or as a diagnostic
    -- object when a mapper emits something that is not parseable JSON.
    function as_json(p_clob in clob) return json_element_t is
        l_obj json_object_t;
    begin
        if p_clob is null or dbms_lob.getlength(p_clob) = 0 then
            return json_object_t();
        end if;
        return json_element_t.parse(p_clob);
    exception
        when others then
            l_obj := json_object_t();
            l_obj.put('unparseable', true);
            l_obj.put('raw', dbms_lob.substr(p_clob, 4000, 1));
            return l_obj;
    end;

    procedure preview_transaction(
        p_payload      in clob,
        o_http_status  out number,
        o_response     out clob
    ) is
        l_operation varchar2(30);
        l_action_request_id varchar2(100);
        l_preview_id varchar2(100);
        l_valid boolean;
        l_errors clob;
        l_result varchar2(30);
        l_status varchar2(40);
        l_existing clob;
        l_root json_object_t := json_object_t();
        l_calls json_array_t := json_array_t();
        l_call json_object_t;
        l_base varchar2(400);
        l_resolution ie_mfcs_orchestrator.t_step_resolution;
        l_endpoint_key varchar2(200);
        l_endpoint_path varchar2(1000);
        l_method varchar2(10);
        l_step_payload clob;
    begin
        select json_value(p_payload, '$.OPERATION_NAME' returning varchar2(30) null on error),
               json_value(p_payload, '$.ACTION_REQUEST_ID' returning varchar2(100) null on error)
          into l_operation, l_action_request_id
          from dual;

        l_root.put('ACTION_REQUEST_ID', l_action_request_id);
        l_root.put('OPERATION_NAME', l_operation);

        if trim(l_operation) is null
           or l_operation not in ('CREATE_STYLE', 'MODIFY_STYLE', 'CREATE_ORDER', 'MODIFY_ORDER', 'CREATE_ALL') then
            l_root.put('VALID', false);
            l_root.put('ERRORS', json_element_t.parse(
                '[{"FIELD":"OPERATION_NAME","CODE":"UNSUPPORTED_OPERATION",'
                || '"MESSAGE":"OPERATION_NAME must be one of CREATE_STYLE, MODIFY_STYLE, CREATE_ORDER, MODIFY_ORDER, CREATE_ALL."}]'));
            l_root.put('MFCS_CALLS', json_array_t());
            o_http_status := 400;
            o_response := l_root.to_clob;
            return;
        end if;

        -- Validate before touching any table.
        l_valid := ie_mfcs_validation.validate_request(p_payload, l_errors);
        if not l_valid then
            l_root.put('VALID', false);
            l_root.put('ERRORS', as_json(l_errors));
            l_root.put('INBOUND_PAYLOAD', as_json(p_payload));
            l_root.put('MFCS_CALLS', json_array_t());
            o_http_status := 422;
            o_response := l_root.to_clob;
            return;
        end if;

        -- Register under a throwaway id so the real request table is untouched
        -- and an existing ACTION_REQUEST_ID is never disturbed.
        l_preview_id := 'PREVIEW-' || lower(rawtohex(sys_guid()));

        ie_mfcs_request.register_request(
            p_action_request_id => l_preview_id,
            p_operation_name => l_operation,
            p_payload_hash => ie_mfcs_request.payload_hash(p_payload),
            p_payload => p_payload,
            o_result => l_result,
            o_status => l_status,
            o_response_payload => l_existing
        );

        ie_mfcs_step.initialize_steps(l_preview_id, l_operation);

        l_base := rtrim(ie_mfcs_config.get_config('MFCS_BASE_URL'), '/');

        for s in (
            select step_code, step_sequence
              from ie_mfcs_prd_request_step
             where action_request_id = l_preview_id
             order by step_sequence
        ) loop
            l_resolution := ie_mfcs_orchestrator.resolve_step(s.step_code, l_operation);
            l_endpoint_key := l_resolution.endpoint_key;

            -- A document that brought its own item numbers reserves none, so the
            -- plan must not show a reservation call. Preview exists to say what
            -- execution would do; a call listed here that will never be made is
            -- exactly the drift this package is meant not to have.
            if s.step_code = 'RESERVE_ITEM_NUMBERS'
               and ie_mfcs_payload.document_item_number(p_payload) is not null then
                l_endpoint_key := null;
            end if;

            l_call := json_object_t();
            l_call.put('sequence', s.step_sequence);
            l_call.put('stepCode', s.step_code);

            if l_endpoint_key is null then
                -- No endpoint the plan can name. Either the step is local, or - for
                -- ENSURE_STYLE_SKUS - which calls it makes depends on what the tenant
                -- already holds, which a preview deliberately does not go and look at.
                l_call.put('local', true);
                l_call.put('method', 'LOCAL');
                if s.step_code = 'SYNC_ORDER_LINES' then
                    l_call.put('description',
                        'Reads the order back and brings its lines to what the document says: '
                        || 'updates through purchaseOrder/details/update, additions through '
                        || 'details/create, and this style''s no-longer-named lines cancelled with '
                        || 'cancelInd. The bulk purchaseOrders/update ignores its details array on '
                        || 'this tenant, so the header step cannot do this work.');
                elsif s.step_code = 'ENSURE_STYLE_SKUS' then
                    l_call.put('description',
                        'Reads the style back and compares it against the requested colour and '
                        || 'size curve. Any combination the style lacks is created here - reserve '
                        || 'a number, create the child, add sourcing and country of manufacture, '
                        || 'approve - then the style is read again to confirm it took. The calls '
                        || 'depend on what the tenant already has, so they cannot be planned ahead.');
                elsif s.step_code = 'RESERVE_ITEM_NUMBERS' then
                    l_call.put('description',
                        'Nothing is reserved: the document carries its own ITEM_NUMBER for the '
                        || 'style and every SKU, so the numbers are simply recorded against the '
                        || 'request and used as they stand. MFCS is told they are '
                        || ie_mfcs_payload.document_item_number_type(p_payload) || ' numbers.');
                else
                    l_call.put('description', 'Performed inside the integration layer; no MFCS call.');
                end if;
            else
                l_method := l_resolution.http_method;
                l_endpoint_path := ie_mfcs_config.get_config(l_endpoint_key);

                begin
                    l_step_payload := ie_mfcs_orchestrator.payload_for_step(l_preview_id, s.step_code);
                exception
                    when others then
                        l_step_payload := null;
                end;

                l_call.put('local', false);
                l_call.put('method', l_method);
                l_call.put('endpointKey', l_endpoint_key);
                l_call.put('endpointPath', l_endpoint_path);
                l_call.put('url', l_base || l_endpoint_path);
                l_call.put('payload', as_json(l_step_payload));
            end if;

            l_calls.append(l_call);
        end loop;

        purge_preview(l_preview_id);

        l_root.put('VALID', true);
        l_root.put('ERRORS', json_array_t());
        l_root.put('INBOUND_PAYLOAD', as_json(p_payload));
        l_root.put('MFCS_CALLS', l_calls);
        l_root.put('NOTE',
            'Preview only - nothing was sent to MFCS. Identifiers that MFCS generates '
            || '(item numbers, order numbers) are not known until the request actually runs, '
            || 'so they appear null or unresolved here.');

        o_http_status := 200;
        o_response := l_root.to_clob;
    exception
        when others then
            if l_preview_id is not null then
                purge_preview(l_preview_id);
            end if;
            o_http_status := 500;
            o_response := '{"VALID":false,"ERRORS":[{"FIELD":null,"CODE":"PREVIEW_FAILED","MESSAGE":"'
                || replace(replace(substr(sqlerrm, 1, 500), '\', '\\'), '"', '\"') || '"}],"MFCS_CALLS":[]}';
    end;
end ie_mfcs_preview;
/

-- ==== 20_packages/12_ie_mfcs_master_data.sql

-- Foundation-data cache.
--
-- Populated three ways, and every row records which:
--   RDS:       read from the tenant's own tables, replicated into RDS
--   ENDPOINT:  read straight from a foundation service that returns rows
--   DERIVED:   harvested from the item or order feed
--
-- The derived route is not a shortcut. The foundation services are publish
-- queues, and which of them hold anything depends on the tenant and the week.
-- On STG in 2026-09, diffid, diffgroup, uda, supplier, store and warehouse
-- publish; merchhier/* still answers HTTP 200 with zero rows.
--
-- The hierarchy is the one thing read from RDS so far, because it is the one
-- thing REST cannot supply on STG: harvesting it from the item feed found 4
-- departments of 21, and validation rejects a department it has not seen.
-- Moving the rest of this cache onto the RDS views is the next piece of work,
-- deliberately kept out of the move itself.
--
-- Every feed that publishes also pages, and fetch_all follows the pages. Reading
-- only the first one was harmless while the feeds were empty and silently
-- truncated them once they filled: diffid stopped at exactly 500.

create or replace package ie_mfcs_master_data authid definer as
    -- Refreshes IE_MFCS_REF_MASTER_DATA so the console can offer dropdowns
    -- without a round trip per keystroke. Failures are recorded per source
    -- rather than aborting the run.
    procedure refresh_all(o_summary out clob);

end ie_mfcs_master_data;
/

create or replace package body ie_mfcs_master_data as

    -- p_keep_existing = 'Y' inserts a missing row and leaves an existing one
    -- untouched. The item harvest uses it for the hierarchy, which load_hierarchy
    -- reads authoritatively from RDS; a plain upsert would relabel those rows
    -- DERIVED on every refresh.
    procedure upsert(
        p_type   in varchar2,
        p_code   in varchar2,
        p_parent in varchar2,
        p_desc   in varchar2,
        p_attrs  in clob,
        p_source in varchar2,
        p_keep_existing in varchar2 default 'N'
    ) is
    begin
        if p_code is null then
            return;
        end if;
        merge into ie_mfcs_ref_master_data d
        using (select p_type dt, p_code dc, nvl(p_parent, '~') pc from dual) s
        on (d.data_type = s.dt and d.data_code = s.dc and d.parent_code = s.pc)
        when matched then update set
            d.description = nvl(p_desc, d.description),
            d.attributes = nvl(p_attrs, d.attributes),
            d.source = p_source,
            d.refreshed_at = systimestamp
            where p_keep_existing = 'N'
        when not matched then insert (data_type, data_code, parent_code, description, attributes, source)
        values (s.dt, s.dc, s.pc, p_desc, p_attrs, p_source);
    end;

    procedure log_refresh(
        p_type in varchar2,
        p_source in varchar2,
        p_status in number,
        p_rows in number,
        p_message in varchar2,
        p_started in timestamp with time zone
    ) is
    begin
        merge into ie_mfcs_log_master_refresh r
        using (select p_type dt from dual) s
        on (r.data_type = s.dt)
        when matched then update set
            r.source = p_source, r.http_status = p_status, r.row_count = p_rows,
            r.message = p_message, r.started_at = p_started, r.completed_at = systimestamp
        when not matched then insert (data_type, source, http_status, row_count, message, started_at, completed_at)
        values (p_type, p_source, p_status, p_rows, p_message, p_started, systimestamp);
    end;

    -- Every row a foundation feed holds, across all its pages.
    --
    -- The envelope is {items, hasMore, links[]}, and the next page is named by an
    -- offsetkey inside the rel=next link, the same key the item harvest pages on.
    -- A few services (codes, banners, channels) answer a bare array instead of the
    -- envelope; that is a single page by construction, and it is why banners and
    -- channels used to fail ORA-40587 on json_object_t.parse.
    --
    -- o_status is the last page's HTTP status. A failure after page one returns
    -- what was read so far with that status, and the caller decides whether a
    -- partial read is worth keeping. o_truncated is true when p_max_pages ran out
    -- with the feed still saying hasMore, so a cap reads as a cap in the refresh
    -- log rather than as the size of the tenant's data.
    function fetch_all(
        p_path      in varchar2,
        p_limit     in number,
        o_status    out number,
        o_truncated out boolean,
        p_max_pages in number default 200
    ) return json_array_t is
        l_all json_array_t := json_array_t();
        l_body clob;
        l_root json_object_t;
        l_items json_array_t;
        l_links json_array_t;
        l_link json_object_t;
        l_offset varchar2(400);
        l_page number := 0;
        l_path varchar2(1000);
    begin
        o_truncated := false;
        loop
            l_page := l_page + 1;
            l_path := p_path || '?limit=' || p_limit;
            if l_offset is not null then
                l_path := l_path || '&offsetkey=' || l_offset;
            end if;

            l_body := ie_mfcs_client.get_json(l_path, o_status);
            exit when o_status not between 200 and 299;

            begin
                l_items := json_array_t.parse(l_body);
                l_root := null;
            exception
                when others then
                    l_root := json_object_t.parse(l_body);
                    l_items := l_root.get_array('items');
            end;

            if l_items is not null then
                for i in 0 .. l_items.get_size - 1 loop
                    l_all.append(l_items.get(i));
                end loop;
            end if;

            l_offset := null;
            if l_root is not null and nvl(l_root.get_string('hasMore'), 'false') = 'true' then
                l_links := l_root.get_array('links');
                if l_links is not null then
                    for i in 0 .. l_links.get_size - 1 loop
                        l_link := treat(l_links.get(i) as json_object_t);
                        if l_link.get_string('rel') = 'next' then
                            l_offset := regexp_substr(l_link.get_string('href'), '[?&]offsetkey=([^&]+)', 1, 1, null, 1);
                        end if;
                    end loop;
                end if;
            end if;

            exit when l_offset is null;
            if l_page >= p_max_pages then
                o_truncated := true;
                exit;
            end if;
        end loop;
        return l_all;
    end;

    procedure load_direct(
        p_type       in varchar2,
        p_path       in varchar2,
        p_code_field in varchar2,
        p_desc_field in varchar2,
        p_limit      in number default 500
    ) is
        l_status number;
        l_truncated boolean;
        l_items json_array_t;
        l_row json_object_t;
        l_count number := 0;
        l_started timestamp with time zone := systimestamp;
        l_source varchar2(200) := 'ENDPOINT:' || p_path;
    begin
        l_items := fetch_all(p_path, p_limit, l_status, l_truncated);
        if l_status not between 200 and 299 and l_items.get_size = 0 then
            log_refresh(p_type, l_source, l_status, 0, 'HTTP ' || l_status, l_started);
            return;
        end if;

        for i in 0 .. l_items.get_size - 1 loop
            l_row := treat(l_items.get(i) as json_object_t);
            upsert(
                p_type => p_type,
                p_code => l_row.get_string(p_code_field),
                p_parent => null,
                p_desc => l_row.get_string(p_desc_field),
                p_attrs => l_row.to_clob,
                p_source => l_source
            );
            l_count := l_count + 1;
        end loop;

        log_refresh(p_type, l_source, l_status, l_count,
            case when l_count = 0 then 'Service returned no rows (empty publish queue).'
                 when l_truncated then 'Stopped at the page cap; the feed has more.'
                 when l_status not between 200 and 299 then 'Partial: a later page answered HTTP ' || l_status || '.'
            end,
            l_started);
    exception
        when others then
            log_refresh(p_type, l_source, l_status, l_count, substr(sqlerrm, 1, 1000), l_started);
    end;

    -- UDAs need more than a code and a description, so they do not go through
    -- load_direct.
    --
    -- Two things depend on this. item/uda/create rejects a row without displayType,
    -- and displayType decides which of udaValue / udaText / udaDate carries the
    -- value - so the mapper has to know a UDA's type before it can send it.
    -- Validation then needs the list of values, to reject a code the tenant will not
    -- accept before a request burns an item number finding out.
    --
    -- Definitions land as UDA; their list-of-values rows land as UDA_VALUE keyed by
    -- parent_code = the udaId, which is what makes the lookup a primary key hit.
    procedure load_udas(p_limit in number default 100) is
        l_status number;
        l_truncated boolean;
        l_items json_array_t;
        l_row json_object_t;
        l_values json_array_t;
        l_value json_object_t;
        l_uda_id varchar2(120);
        l_count number := 0;
        l_values_count number := 0;
        l_started timestamp with time zone := systimestamp;
        l_path varchar2(200) := '/MerchIntegrations/services/foundation/uda';
        l_source varchar2(200) := 'ENDPOINT:' || l_path;
    begin
        -- A smaller page than the other feeds: each UDA row carries its whole
        -- value list, and Style (66040) alone is ~2MB of values on UAT.
        l_items := fetch_all(l_path, p_limit, l_status, l_truncated);
        if l_status not between 200 and 299 and l_items.get_size = 0 then
            log_refresh('UDA', l_source, l_status, 0, 'HTTP ' || l_status, l_started);
            return;
        end if;

        for i in 0 .. l_items.get_size - 1 loop
            l_row := treat(l_items.get(i) as json_object_t);
            l_uda_id := to_char(l_row.get_number('udaId'));

            upsert(
                p_type   => 'UDA',
                p_code   => l_uda_id,
                p_parent => null,
                -- udaDescription, not udaDesc. The earlier load_direct call asked for
                -- the wrong name and stored a null description for every row.
                p_desc   => l_row.get_string('udaDescription'),
                p_attrs  => l_row.to_clob,
                p_source => l_source
            );
            l_count := l_count + 1;

            -- FF and DT UDAs carry "udaListOfValues": null rather than omitting the
            -- key, so has() is true and get_array returns a null object. Calling
            -- get_size on that is ORA-30625, which aborted the whole load at the
            -- first free-form UDA and left every value after it unloaded.
            l_values := null;
            if l_row.has('udaListOfValues') and l_row.get('udaListOfValues').is_array then
                l_values := l_row.get_array('udaListOfValues');
            end if;
            if l_values is not null then
                for j in 0 .. l_values.get_size - 1 loop
                    l_value := treat(l_values.get(j) as json_object_t);
                    upsert(
                        p_type   => 'UDA_VALUE',
                        p_code   => to_char(l_value.get_number('udaValue')),
                        p_parent => l_uda_id,
                        p_desc   => l_value.get_string('udaValueDescription'),
                        p_attrs  => l_value.to_clob,
                        p_source => l_source
                    );
                    l_values_count := l_values_count + 1;
                end loop;
            end if;
        end loop;

        log_refresh('UDA', l_source, l_status, l_count,
            case when l_count = 0
                 then 'Service returned no rows (empty publish queue).'
                 else 'Loaded ' || l_values_count || ' list-of-values rows as UDA_VALUE.'
                      || case when l_truncated then ' Stopped at the page cap; the feed has more.' end
            end,
            l_started);
    exception
        when others then
            log_refresh('UDA', l_source, l_status, l_count, substr(sqlerrm, 1, 1000), l_started);
    end;

    -- Differentiators land as DIFF_<diffType> - DIFF_C, DIFF_S, DIFF_HL and so on -
    -- which is what the item harvest writes too, so validation and the console's
    -- lists see one set whichever route a value arrived by. They used to land as
    -- DIFF_SVC, a type nothing read.
    --
    -- The type set is the tenant's, not ours. STG gained HL (High Level Colour)
    -- and LL (Low Level Colour) in 2026-09 and labelled SC "Supplier Colour - to be
    -- deleted"; loading by the row's own type is what keeps that visible here.
    procedure load_diffs(p_limit in number default 500) is
        l_status number;
        l_truncated boolean;
        l_items json_array_t;
        l_row json_object_t;
        l_count number := 0;
        l_started timestamp with time zone := systimestamp;
        l_path varchar2(200) := '/MerchIntegrations/services/foundation/diffid';
        l_source varchar2(200) := 'ENDPOINT:' || l_path;
    begin
        l_items := fetch_all(l_path, p_limit, l_status, l_truncated);
        if l_status not between 200 and 299 and l_items.get_size = 0 then
            log_refresh('DIFF', l_source, l_status, 0, 'HTTP ' || l_status, l_started);
            return;
        end if;

        for i in 0 .. l_items.get_size - 1 loop
            l_row := treat(l_items.get(i) as json_object_t);
            upsert(
                p_type   => 'DIFF_' || nvl(l_row.get_string('diffType'), 'X'),
                p_code   => l_row.get_string('diffId'),
                p_parent => null,
                p_desc   => l_row.get_string('diffDescription'),
                p_attrs  => l_row.to_clob,
                p_source => l_source
            );
            l_count := l_count + 1;
        end loop;

        log_refresh('DIFF', l_source, l_status, l_count,
            case when l_count = 0 then 'Service returned no rows (empty publish queue).'
                 when l_truncated then 'Stopped at the page cap; the feed has more.'
            end,
            l_started);
    exception
        when others then
            log_refresh('DIFF', l_source, l_status, l_count, substr(sqlerrm, 1, 1000), l_started);
    end;

    -- A differentiator group says which diffs are legal children of a parent that
    -- carries it: MFCS rejects a child whose colour is outside the parent's group.
    -- Groups land as DIFF_GROUP (attributes carry diffType); members land as
    -- DIFF_GROUP_MEMBER with parent_code = the group, so "is this size in that
    -- group" is a primary key hit.
    --
    -- Members are replaced per group rather than merged. The group's row in the
    -- feed is the whole membership, and a merge would keep a diff the tenant has
    -- since removed from the group - which validation would then wrongly accept.
    procedure load_diff_groups(p_limit in number default 100) is
        l_status number;
        l_truncated boolean;
        l_items json_array_t;
        l_row json_object_t;
        l_details json_array_t;
        l_detail json_object_t;
        l_group varchar2(120);
        l_count number := 0;
        l_members number := 0;
        l_started timestamp with time zone := systimestamp;
        l_path varchar2(200) := '/MerchIntegrations/services/foundation/diffgroup';
        l_source varchar2(200) := 'ENDPOINT:' || l_path;
    begin
        l_items := fetch_all(l_path, p_limit, l_status, l_truncated);
        if l_status not between 200 and 299 and l_items.get_size = 0 then
            log_refresh('DIFF_GROUP', l_source, l_status, 0, 'HTTP ' || l_status, l_started);
            return;
        end if;

        for i in 0 .. l_items.get_size - 1 loop
            l_row := treat(l_items.get(i) as json_object_t);
            l_group := l_row.get_string('diffGroupId');
            continue when l_group is null;

            l_details := null;
            if l_row.has('details') and l_row.get('details').is_array then
                l_details := l_row.get_array('details');
            end if;

            -- The group row without its member list; the members are rows of
            -- their own, and repeating them here would store every group twice.
            l_row.remove('details');
            upsert('DIFF_GROUP', l_group, null, l_row.get_string('diffGroupDescription'),
                   l_row.to_clob, l_source);
            l_count := l_count + 1;

            delete from ie_mfcs_ref_master_data
             where data_type = 'DIFF_GROUP_MEMBER'
               and parent_code = l_group;

            if l_details is not null then
                for j in 0 .. l_details.get_size - 1 loop
                    l_detail := treat(l_details.get(j) as json_object_t);
                    upsert('DIFF_GROUP_MEMBER', l_detail.get_string('diffId'), l_group,
                           null, l_detail.to_clob, l_source);
                    l_members := l_members + 1;
                end loop;
            end if;
        end loop;

        log_refresh('DIFF_GROUP', l_source, l_status, l_count,
            case when l_count = 0 then 'Service returned no rows (empty publish queue).'
                 else 'Loaded ' || l_members || ' member rows as DIFF_GROUP_MEMBER.'
                      || case when l_truncated then ' Stopped at the page cap; the feed has more.' end
            end,
            l_started);
    exception
        when others then
            log_refresh('DIFF_GROUP', l_source, l_status, l_count, substr(sqlerrm, 1, 1000), l_started);
    end;

    procedure harvest_from_items(p_pages in number default 10, p_limit in number default 200) is
        l_status number;
        l_body clob;
        l_root json_object_t;
        l_items json_array_t;
        l_it json_object_t;
        l_sups json_array_t;
        l_sup json_object_t;
        l_started timestamp with time zone := systimestamp;
        l_source varchar2(200) := 'DERIVED:/services/foundation/item';
        l_path varchar2(400);
        l_offset varchar2(200);
        l_items_seen number := 0;
        l_more boolean := true;
        l_page number := 0;
        l_dept varchar2(120);
        l_class varchar2(120);
    begin
        while l_more and l_page < p_pages loop
            l_page := l_page + 1;
            l_path := '/MerchIntegrations/services/foundation/item?limit=' || p_limit;
            if l_offset is not null then
                l_path := l_path || '&offsetkey=' || l_offset;
            end if;

            l_body := ie_mfcs_client.get_json(l_path, l_status);
            exit when l_status not between 200 and 299;

            l_root := json_object_t.parse(l_body);
            l_items := l_root.get_array('items');
            exit when l_items is null or l_items.get_size = 0;

            for i in 0 .. l_items.get_size - 1 loop
                l_it := treat(l_items.get(i) as json_object_t);
                l_items_seen := l_items_seen + 1;
                l_offset := l_it.get_string('item');

                l_dept := to_char(l_it.get_number('dept'));
                l_class := to_char(l_it.get_number('class'));

                -- Insert-only: RDS is the authority for the hierarchy, and the
                -- harvest only fills in a code it has not supplied.
                upsert('DEPARTMENT', l_dept, null, l_it.get_string('deptName'), null, l_source, 'Y');
                upsert('CLASS', l_class, l_dept, l_it.get_string('className'), null, l_source, 'Y');
                upsert('SUBCLASS', to_char(l_it.get_number('subclass')),
                       l_dept || '.' || l_class, l_it.get_string('subclassName'), null, l_source, 'Y');

                -- diff1/diff2 carry their own type flag (C = colour, S = size).
                if l_it.get_string('diff1') is not null then
                    upsert('DIFF_' || nvl(l_it.get_string('diff1Type'), 'X'),
                           l_it.get_string('diff1'), null, null, null, l_source);
                end if;
                if l_it.get_string('diff2') is not null then
                    upsert('DIFF_' || nvl(l_it.get_string('diff2Type'), 'X'),
                           l_it.get_string('diff2'), null, null, null, l_source);
                end if;

                if l_it.get_string('standardUom') is not null then
                    upsert('UOM', l_it.get_string('standardUom'), null, null, null, l_source);
                end if;

                begin
                    l_sups := l_it.get_array('supplier');
                    if l_sups is not null then
                        for j in 0 .. l_sups.get_size - 1 loop
                            l_sup := treat(l_sups.get(j) as json_object_t);
                            upsert('SUPPLIER', to_char(l_sup.get_number('supplier')), null,
                                   l_sup.get_string('supplierName'), l_sup.to_clob, l_source);
                        end loop;
                    end if;
                exception when others then null;
                end;
            end loop;

            l_more := nvl(l_root.get_string('hasMore'), 'false') = 'true';
        end loop;

        log_refresh('DERIVED_FROM_ITEMS', l_source, l_status, l_items_seen,
            'Scanned ' || l_items_seen || ' items across ' || l_page || ' page(s).', l_started);
    exception
        when others then
            log_refresh('DERIVED_FROM_ITEMS', l_source, l_status, l_items_seen, substr(sqlerrm, 1, 1000), l_started);
    end;

    procedure harvest_from_orders(p_limit in number default 200) is
        l_status number;
        l_body clob;
        l_items json_array_t;
        l_o json_object_t;
        l_started timestamp with time zone := systimestamp;
        l_source varchar2(200) := 'DERIVED:/services/procurement/order';
        l_seen number := 0;
    begin
        l_body := ie_mfcs_client.get_json('/MerchIntegrations/services/procurement/order?limit=' || p_limit, l_status);
        if l_status not between 200 and 299 then
            log_refresh('DERIVED_FROM_ORDERS', l_source, l_status, 0, 'HTTP ' || l_status, l_started);
            return;
        end if;

        l_items := json_object_t.parse(l_body).get_array('items');
        for i in 0 .. l_items.get_size - 1 loop
            l_o := treat(l_items.get(i) as json_object_t);
            l_seen := l_seen + 1;
            upsert('SUPPLIER', to_char(l_o.get_number('supplier')), null, null, null, l_source);
            upsert('CURRENCY', l_o.get_string('currencyCode'), null, null, null, l_source);
            if l_o.get_number('virtualWarehouse') is not null then
                upsert('LOCATION_W', to_char(l_o.get_number('virtualWarehouse')), null,
                       'Virtual warehouse', null, l_source);
            end if;
            if l_o.get_number('physicalLocation') is not null then
                upsert('LOCATION_P', to_char(l_o.get_number('physicalLocation')), null,
                       'Physical location', null, l_source);
            end if;
            if l_o.get_string('terms') is not null then
                upsert('TERMS', l_o.get_string('terms'), null, l_o.get_string('termsCode'), null, l_source);
            end if;
        end loop;

        log_refresh('DERIVED_FROM_ORDERS', l_source, l_status, l_seen,
            'Scanned ' || l_seen || ' orders.', l_started);
    exception
        when others then
            log_refresh('DERIVED_FROM_ORDERS', l_source, l_status, l_seen, substr(sqlerrm, 1, 1000), l_started);
    end;

    -- administration/operations/codes returns the RMS code_detail table: ~797 code
    -- types, each with its own values. Unlike the other foundation services this one
    -- actually has data, so it is the authoritative source for fixed-value dropdowns
    -- that would otherwise be hardcoded in IE_MFCS_CFG_SETTING or inferred from items.
    --
    -- Stored as data_type CODE_<codeType>, with the code type as parent_code so the
    -- console can group them.
    procedure load_code_details(p_limit in number default 5000) is
        l_status number;
        l_body clob;
        l_types json_array_t;
        l_type json_object_t;
        l_details json_array_t;
        l_detail json_object_t;
        l_started timestamp with time zone := systimestamp;
        l_source varchar2(200) := 'ENDPOINT:/services/administration/operations/codes';
        l_count number := 0;
        l_code_type varchar2(40);
    begin
        l_body := ie_mfcs_client.get_json(
            '/MerchIntegrations/services/administration/operations/codes?limit=' || p_limit, l_status);
        if l_status not between 200 and 299 then
            log_refresh('CODE_DETAIL', l_source, l_status, 0, 'HTTP ' || l_status, l_started);
            return;
        end if;

        -- This service answers with a bare array, not the usual {items:[...]} envelope.
        begin
            l_types := json_array_t.parse(l_body);
        exception
            when others then
                l_types := json_object_t.parse(l_body).get_array('items');
        end;

        for i in 0 .. l_types.get_size - 1 loop
            l_type := treat(l_types.get(i) as json_object_t);
            l_code_type := l_type.get_string('codeType');

            -- The code type itself, so a caller can list what exists.
            upsert('CODE_TYPE', l_code_type, null, l_type.get_string('description'), null, l_source);

            l_details := l_type.get_array('details');
            if l_details is not null then
                for j in 0 .. l_details.get_size - 1 loop
                    l_detail := treat(l_details.get(j) as json_object_t);
                    upsert(
                        p_type => 'CODE_' || l_code_type,
                        p_code => l_detail.get_string('code'),
                        p_parent => l_code_type,
                        p_desc => l_detail.get_string('codeDescription'),
                        p_attrs => l_detail.to_clob,
                        p_source => l_source);
                    l_count := l_count + 1;
                end loop;
            end if;
        end loop;

        log_refresh('CODE_DETAIL', l_source, l_status, l_count,
            'Loaded ' || l_count || ' value(s) across ' || l_types.get_size || ' code type(s).',
            l_started);
    exception
        when others then
            log_refresh('CODE_DETAIL', l_source, l_status, l_count, substr(sqlerrm, 1, 1000), l_started);
    end;

    -- The merchandise hierarchy, from the tenant's own GROUPS, DEPS, CLASS and
    -- SUBCLASS through the IE_MFCS_VW_* views, which also drop rows RDS keeps
    -- after a delete. Rows land in the shape the item harvest writes - CLASS
    -- under its department, SUBCLASS under "dept.class" - because validation and
    -- the console lists read exactly that shape.
    --
    -- Merges, never deletes. A code missing from RDS is left in place rather
    -- than removed: if a grant were revoked the views would read empty, and
    -- deleting on that basis would empty the hierarchy - and validation accepts
    -- anything for a type it holds no rows of.
    procedure load_hierarchy is
        l_count number := 0;
        l_started timestamp with time zone := systimestamp;
        c_source constant varchar2(200) := 'RDS:MFCS_RDS.RDS_WV_GROUPS/DEPS/CLASS/SUBCLASS';
    begin
        for r in (select group_no, group_name, division from ie_mfcs_vw_merch_group) loop
            upsert('MERCH_GROUP', to_char(r.group_no), null, r.group_name,
                   '{"division":"' || to_char(r.division) || '"}', c_source);
            l_count := l_count + 1;
        end loop;

        for r in (select dept, dept_name, group_no from ie_mfcs_vw_department) loop
            upsert('DEPARTMENT', to_char(r.dept), null, r.dept_name,
                   '{"groupNo":"' || to_char(r.group_no) || '"}', c_source);
            l_count := l_count + 1;
        end loop;

        for r in (select dept, class, class_name, class_id from ie_mfcs_vw_class) loop
            upsert('CLASS', to_char(r.class), to_char(r.dept), r.class_name,
                   '{"classId":"' || to_char(r.class_id) || '"}', c_source);
            l_count := l_count + 1;
        end loop;

        for r in (select dept, class, subclass, sub_name, subclass_id from ie_mfcs_vw_subclass) loop
            upsert('SUBCLASS', to_char(r.subclass), to_char(r.dept) || '.' || to_char(r.class), r.sub_name,
                   '{"subclassId":"' || to_char(r.subclass_id) || '"}', c_source);
            l_count := l_count + 1;
        end loop;

        log_refresh('RDS_HIERARCHY', c_source, null, l_count,
            case when l_count = 0 then 'The RDS hierarchy views returned no rows - check the grants on MFCS_RDS.' end,
            l_started);
    exception
        when others then
            log_refresh('RDS_HIERARCHY', c_source, null, l_count, substr(sqlerrm, 1, 1000), l_started);
    end;

    procedure refresh_all(o_summary out clob) is
        l_root json_object_t := json_object_t();
        l_arr json_array_t := json_array_t();
        l_row json_object_t;
    begin
        -- First, so the item harvest below finds the hierarchy already there
        -- and leaves it alone.
        load_hierarchy;

        -- Services that return rows on this tenant.
        load_direct('BRAND', '/MerchIntegrations/services/item/brands', 'brandName', 'brandDescription');
        load_direct('SEASON', '/MerchIntegrations/services/item/foundation/seasons', 'season', 'description');
        load_direct('ORG_HIER', '/MerchIntegrations/services/foundation/orghier', 'hierarchyId', 'hierarchyName');
        load_direct('BANNER', '/MerchIntegrations/services/foundation/banners', 'bannerId', 'bannerName');
        load_direct('CHANNEL', '/MerchIntegrations/services/foundation/channels', 'channelId', 'channelName');
        load_code_details;
        load_udas;

        -- Attempted anyway, so the refresh log records that it is still empty
        -- rather than leaving it a mystery.
        load_direct('DEPARTMENT_SVC', '/MerchIntegrations/services/foundation/merchhier/deps', 'dept', 'deptName');
        load_direct('SUPPLIER_SVC', '/MerchIntegrations/services/foundation/supplier', 'supplier', 'supplierName');
        -- warehouse / warehouseName, not wh / whName. Asking for the wrong names
        -- loaded nothing at all, silently, for as long as this call has existed -
        -- the same failure the UDA loader had with udaDesc. The row also carries
        -- physicalWarehouse and primaryVirtualWarehouse, which is where the
        -- physical-to-virtual translation comes from.
        load_direct('WAREHOUSE_SVC', '/MerchIntegrations/services/foundation/warehouse', 'warehouse', 'warehouseName');
        load_direct('STORE_SVC', '/MerchIntegrations/services/foundation/store', 'store', 'storeName');

        harvest_from_items;
        harvest_from_orders;

        -- After the harvest, not before. The harvest writes the same DIFF_* rows
        -- from the item feed and stamps them DERIVED; loading the diff service
        -- last leaves every diff the service publishes recorded as ENDPOINT, with
        -- the service's description, and DERIVED marking only what it does not.
        load_diffs;
        load_diff_groups;
        commit;

        for r in (
            select m.data_type, count(*) cnt, max(m.source) src,
                   to_char(max(m.refreshed_at), 'YYYY-MM-DD"T"HH24:MI:SS') last_refresh
              from ie_mfcs_ref_master_data m
             group by m.data_type
             order by m.data_type
        ) loop
            l_row := json_object_t();
            l_row.put('dataType', r.data_type);
            l_row.put('count', r.cnt);
            l_row.put('source', r.src);
            l_row.put('refreshedAt', r.last_refresh);
            l_arr.append(l_row);
        end loop;
        l_root.put('cached', l_arr);

        l_arr := json_array_t();
        for r in (
            select data_type, source, http_status, row_count, message,
                   to_char(completed_at, 'YYYY-MM-DD"T"HH24:MI:SS') completed
              from ie_mfcs_log_master_refresh order by data_type
        ) loop
            l_row := json_object_t();
            l_row.put('dataType', r.data_type);
            l_row.put('source', r.source);
            l_row.put('httpStatus', r.http_status);
            l_row.put('rowCount', r.row_count);
            l_row.put('message', r.message);
            l_row.put('completedAt', r.completed);
            l_arr.append(l_row);
        end loop;
        l_root.put('log', l_arr);

        o_summary := l_root.to_clob;
    end;
end ie_mfcs_master_data;
/

-- ==== 20_packages/13_ie_mfcs_browse.sql

-- Live style and order reads for the console's browse screen.
--
-- Deliberately uncached: a browse screen should show current tenant state.

create or replace package ie_mfcs_browse authid definer as
    function list_styles(
        p_limit      in number default 50,
        p_dept       in varchar2 default null,
        p_item_level in varchar2 default '1'
    ) return clob;

    function list_orders(
        p_limit    in number default 50,
        p_supplier in varchar2 default null
    ) return clob;

    -- p_with_skus attaches the style's child SKUs under resolved.skus.
    --
    -- The MerchIntegrations item service cannot do this: it has no itemParent
    -- filter, its response schema carries no child collection (itemParent and
    -- itemGrandparent point upward, referenceItem holds level-3 UPCs), and no
    -- child-item service exists among its 90 GET paths.
    --
    -- The tenant also serves an older API family that is absent from the
    -- MerchIntegrations OpenAPI document:
    --
    --   GET /RmsReSTServices/services/private/Item/itemDetail?item=<style>
    --
    -- which returns the style together with its children in a single call. That
    -- is used first. It carries fewer fields than the MerchIntegrations read, so
    -- each child is then fetched in full for the detail regions.
    --
    -- Because that service is undocumented for this tenant, a scan of the item
    -- feed remains as a fallback. resolved.source records which path was taken.
    function get_style(
        p_item      in varchar2,
        p_with_skus in varchar2 default 'N'
    ) return clob;

    -- p_enrich resolves what an order read does not carry but a MODIFY_ORDER
    -- request needs: the parent style behind the SKUs on the detail lines, and
    -- each line's display size, reverse-mapped from its MFCS size diff through
    -- MAP.SIZE.*. Adds an "resolved" object at the root and on each line.
    --
    -- Without it a browsed order fails validation on STYLE_REQUIRED_OR_RESOLVABLE
    -- and MAPPING_NOT_FOUND.
    function get_order(
        p_order_no in varchar2,
        p_enrich   in varchar2 default 'Y'
    ) return clob;
end ie_mfcs_browse;
/

create or replace package body ie_mfcs_browse as

    -- Upstream failures must not be served to the console as HTTP 200 with an
    -- HTML body. MFCS answers an expired token with an HTML 401 page; passing
    -- that through untouched makes a dead credential look like an endpoint that
    -- works and simply has no data, which is exactly the wrong diagnosis.
    function passthrough(p_path in varchar2) return clob is
        l_status number;
        l_body clob;
        l_err json_object_t;
    begin
        l_body := ie_mfcs_client.get_json(p_path, l_status);
        if l_status between 200 and 299 then
            return l_body;
        end if;
        l_err := json_object_t();
        l_err.put('error', 'MFCS returned HTTP ' || l_status);
        l_err.put('httpStatus', l_status);
        l_err.put('path', p_path);
        -- Tokens are fetched and refreshed by apex_web_service, so a 401 is never
        -- an expired token here: it is the credential itself, or the workspace
        -- that holds it not being found.
        l_err.put('hint', case when l_status = 401
                               then 'MFCS rejected the credential - check the MFCS_OAUTH web credential''s id and secret, and MFCS_APEX_WORKSPACE.'
                               when l_status = 403
                               then 'The credential is for a different tenant than MFCS_BASE_URL.'
                               else 'See detail for what MFCS reported.' end);
        l_err.put('detail', substr(dbms_lob.substr(l_body, 900, 1), 1, 900));
        l_err.put('items', json_array_t());
        return l_err.to_clob;
    end;

    function display_size(p_diff in varchar2) return varchar2 is
        l_code varchar2(120);
    begin
        if p_diff is null then
            return null;
        end if;
        -- The differentiator's own description, which is what a buyer calls it.
        -- This used to scan MAP.SIZE.* config backwards for a row whose value was
        -- this diff; master data holds the same answer as a primary key hit.
        select description
          into l_code
          from ie_mfcs_ref_master_data
         where data_type = 'DIFF_S'
           and data_code = p_diff
           and parent_code = '~';
        return l_code;
    exception
        when no_data_found then return null;
    end;

    function list_styles(
        p_limit      in number default 50,
        p_dept       in varchar2 default null,
        p_item_level in varchar2 default '1'
    ) return clob is
        l_status number;
        l_path varchar2(600);
    begin
        l_path := '/MerchIntegrations/services/foundation/item?limit=' || nvl(p_limit, 50);
        if p_item_level is not null then
            l_path := l_path || '&itemLevel=' || p_item_level;
        end if;
        if p_dept is not null then
            l_path := l_path || '&deptId=' || p_dept;
        end if;
        return passthrough(l_path);
    end;

    function list_orders(
        p_limit    in number default 50,
        p_supplier in varchar2 default null
    ) return clob is
        l_status number;
        l_path varchar2(600);
    begin
        l_path := '/MerchIntegrations/services/procurement/order?limit=' || nvl(p_limit, 50);
        if p_supplier is not null then
            l_path := l_path || '&supplier=' || p_supplier;
        end if;
        return passthrough(l_path);
    end;

    -- Child item numbers for a style, via the RmsReSTServices item hierarchy read.
    -- Returns an empty collection if the service is unavailable, so the caller can
    -- fall back.
    function child_numbers_via_item_detail(
        p_item   in varchar2,
        o_ok     out boolean
    ) return apex_t_varchar2 is
        l_status number;
        l_body clob;
        l_arr json_array_t;
        l_row json_object_t;
        l_out apex_t_varchar2 := apex_t_varchar2();
    begin
        o_ok := false;
        l_body := ie_mfcs_client.get_json(
            '/RmsReSTServices/services/private/Item/itemDetail?item=' || p_item, l_status);
        if l_status not between 200 and 299 then
            return l_out;
        end if;

        l_arr := json_array_t.parse(l_body);
        o_ok := true;
        for i in 0 .. l_arr.get_size - 1 loop
            l_row := treat(l_arr.get(i) as json_object_t);
            -- The array is not ordered parent-first, so match on the relationship
            -- rather than on position.
            if l_row.get_string('itemParent') = p_item then
                apex_string.push(l_out, l_row.get_string('item'));
            end if;
        end loop;
        return l_out;
    exception
        when others then
            o_ok := false;
            return apex_t_varchar2();
    end;

    -- Fallback: page the item feed and match itemParent. Projects only the two
    -- fields the match needs via the include parameter, which takes a 200-row page
    -- from roughly 1.1MB to 30KB.
    function child_numbers_via_scan(
        p_item      in varchar2,
        p_dept      in number,
        o_scanned   out pls_integer,
        o_truncated out boolean
    ) return apex_t_varchar2 is
        c_max_pages constant pls_integer := 25;
        c_page_size constant pls_integer := 500;
        l_status number;
        l_body clob;
        l_feed json_object_t;
        l_items json_array_t;
        l_row json_object_t;
        l_out apex_t_varchar2 := apex_t_varchar2();
        l_page pls_integer := 0;
        l_more boolean := true;
        l_offset varchar2(200);
        l_path varchar2(1000);
    begin
        o_scanned := 0;
        while l_more and l_page < c_max_pages loop
            l_page := l_page + 1;
            l_path := '/MerchIntegrations/services/foundation/item?itemLevel=2&limit='
                   || c_page_size || '&include=items.item,items.itemParent';
            if p_dept is not null then
                l_path := l_path || '&deptId=' || p_dept;
            end if;
            if l_offset is not null then
                l_path := l_path || '&offsetkey=' || l_offset;
            end if;

            l_body := ie_mfcs_client.get_json(l_path, l_status);
            exit when l_status not between 200 and 299;

            l_feed := json_object_t.parse(l_body);
            l_items := l_feed.get_array('items');
            exit when l_items is null or l_items.get_size = 0;

            for i in 0 .. l_items.get_size - 1 loop
                l_row := treat(l_items.get(i) as json_object_t);
                l_offset := l_row.get_string('item');
                o_scanned := o_scanned + 1;
                if l_row.get_string('itemParent') = p_item then
                    apex_string.push(l_out, l_row.get_string('item'));
                end if;
            end loop;

            l_more := nvl(l_feed.get_string('hasMore'), 'false') = 'true';
        end loop;
        o_truncated := l_page >= c_max_pages and l_more;
        return l_out;
    end;

    function get_style(
        p_item      in varchar2,
        p_with_skus in varchar2 default 'N'
    ) return clob is
        l_status number;
        l_body clob;
        l_root json_object_t;
        l_items json_array_t;
        l_style json_object_t;
        l_dept number;
        l_meta json_object_t;
        l_numbers apex_t_varchar2;
        l_skus json_array_t := json_array_t();
        l_ok boolean;
        l_scanned pls_integer := 0;
        l_truncated boolean := false;
        l_source varchar2(60);
        l_child_body clob;
        l_child_items json_array_t;
    begin
        l_body := passthrough('/MerchIntegrations/services/foundation/item/' || p_item);

        if nvl(p_with_skus, 'N') <> 'Y'
           or json_object_t.parse(l_body).has('error') then
            return l_body;
        end if;

        l_root := json_object_t.parse(l_body);
        l_items := l_root.get_array('items');
        if l_items is null or l_items.get_size = 0 then
            return l_body;
        end if;
        l_style := treat(l_items.get(0) as json_object_t);

        if nvl(l_style.get_number('itemLevel'), 1) <> 1 then
            l_meta := json_object_t();
            l_meta.put('skus', json_array_t());
            l_meta.put('skuCount', 0);
            l_meta.put('source', 'none');
            l_meta.put('note', 'Not a parent item.');
            l_style.put('resolved', l_meta);
            return l_root.to_clob;
        end if;

        l_dept := l_style.get_number('dept');

        l_numbers := child_numbers_via_item_detail(p_item, l_ok);
        if l_ok then
            l_source := 'itemDetail';
        else
            l_numbers := child_numbers_via_scan(p_item, l_dept, l_scanned, l_truncated);
            l_source := 'feed scan';
        end if;

        -- itemDetail carries a thinner document than the MerchIntegrations read,
        -- so fetch each child in full for the supplier, country and UDA regions.
        for i in 1 .. l_numbers.count loop
            l_child_body := ie_mfcs_client.get_json(
                '/MerchIntegrations/services/foundation/item/' || l_numbers(i), l_status);
            if l_status between 200 and 299 then
                l_child_items := json_object_t.parse(l_child_body).get_array('items');
                if l_child_items is not null and l_child_items.get_size > 0 then
                    l_skus.append(treat(l_child_items.get(0) as json_object_t));
                end if;
            end if;
        end loop;

        l_meta := json_object_t();
        l_meta.put('skus', l_skus);
        l_meta.put('skuCount', l_skus.get_size);
        l_meta.put('source', l_source);
        l_meta.put('truncated', l_truncated);
        if l_source = 'itemDetail' then
            l_meta.put('note',
                'Children read from RmsReSTServices Item/itemDetail, which returns a '
                || 'style together with its children in one call.');
        else
            l_meta.put('itemsScanned', l_scanned);
            l_meta.put('note',
                'itemDetail was unavailable, so children were found by scanning the '
                || 'item feed. A SKU that is not approved and published will not appear.');
        end if;
        l_style.put('resolved', l_meta);

        return l_root.to_clob;
    end;

    function get_order(
        p_order_no in varchar2,
        p_enrich   in varchar2 default 'Y'
    ) return clob is
        l_status number;
        l_body clob;
        l_root json_object_t;
        l_orders json_array_t;
        l_order json_object_t;
        l_details json_array_t;
        l_line json_object_t;
        l_item_body clob;
        l_item json_object_t;
        l_meta json_object_t;
        l_order_meta json_object_t;
        l_style varchar2(30);
        l_colour varchar2(120);
    begin
        l_body := passthrough('/MerchIntegrations/services/procurement/order/' || p_order_no);
        if nvl(p_enrich, 'Y') <> 'Y'
           or json_object_t.parse(l_body).has('error') then
            return l_body;
        end if;

        l_root := json_object_t.parse(l_body);
        l_orders := l_root.get_array('items');
        if l_orders is null or l_orders.get_size = 0 then
            return l_body;
        end if;

        l_order := treat(l_orders.get(0) as json_object_t);
        l_details := l_order.get_array('details');
        if l_details is null then
            return l_body;
        end if;

        for i in 0 .. l_details.get_size - 1 loop
            l_line := treat(l_details.get(i) as json_object_t);
            begin
                l_item_body := ie_mfcs_client.get_json(
                    '/MerchIntegrations/services/foundation/item/' || l_line.get_string('item'),
                    l_status);
                if l_status between 200 and 299 then
                    l_item := treat(json_object_t.parse(l_item_body).get_array('items').get(0) as json_object_t);
                    l_meta := json_object_t();
                    l_meta.put('itemParent', l_item.get_string('itemParent'));
                    l_meta.put('diff1', l_item.get_string('diff1'));
                    l_meta.put('diff2', l_item.get_string('diff2'));
                    l_meta.put('displaySize', display_size(l_item.get_string('diff2')));
                    l_meta.put('itemDescription', l_item.get_string('itemDescription'));
                    l_line.put('resolved', l_meta);

                    if l_style is null then
                        l_style := l_item.get_string('itemParent');
                    end if;
                    if l_colour is null then
                        l_colour := l_item.get_string('diff1');
                    end if;
                end if;
            exception
                when others then null;
            end;
        end loop;

        l_order_meta := json_object_t();
        l_order_meta.put('style', l_style);
        l_order_meta.put('colour', l_colour);
        l_order_meta.put('enriched', true);
        l_order.put('resolved', l_order_meta);

        return l_root.to_clob;
    end;
end ie_mfcs_browse;
/

-- ==== 20_packages/14_ie_mfcs_api.sql

-- Public entry points behind the ORDS handlers.
--
-- The only package ORDS calls for transaction work. Each procedure returns the
-- HTTP status and the response body; the handlers emit them verbatim, so
-- everything the console or Office sees is decided here, not in the handler.
--
-- Application error codes used across the packages:
--   -20820        unknown payload mapper (a compile-time wiring bug)
--   -20830        MFCS reservation response carried no item number
--   -20950        MFCS rejected a call (HTTP 4xx/5xx with a readable body)
--   -20951        MFCS unavailable: HTTP 503 or the nightly batch window
--   -20952        transport failed after the request may have been sent;
--                 the outcome is unknown until ie_mfcs_recovery resolves it
--   -20960..20965 ENSURE_STYLE_SKUS: lookup failed, combinations missing,
--                 parent unreadable, unmapped size, no sourcing, verify failed

create or replace package ie_mfcs_api authid definer as
    -- Validates, registers and executes an Office document. Replays the stored
    -- outcome for a duplicate, 409s a conflicting reuse of the id, 422s a
    -- document that fails validation.
    procedure submit_transaction(
        p_payload      in clob,
        o_http_status  out number,
        o_response     out clob
    );

    -- Runs validation only. Nothing is registered and nothing reaches MFCS.
    procedure validate_transaction(
        p_payload      in clob,
        o_http_status  out number,
        o_response     out clob
    );

    -- Returns the current status document for a registered request.
    procedure get_transaction(
        p_action_request_id in varchar2,
        o_http_status       out number,
        o_response          out clob
    );

    -- Re-enters a partially completed request: succeeded steps are skipped,
    -- the failed or unknown step is retried, and execution continues from
    -- there. A request that failed on a bad stored value needs a fresh
    -- request instead - resume replays the stored payload.
    procedure resume_transaction(
        p_action_request_id in varchar2,
        o_http_status       out number,
        o_response          out clob
    );
end ie_mfcs_api;
/

create or replace package body ie_mfcs_api as
    function simple_error(
        p_action_request_id in varchar2,
        p_status            in varchar2,
        p_retryable         in varchar2,
        p_field             in varchar2,
        p_code              in varchar2,
        p_message           in varchar2
    ) return clob is
    begin
        return '{"ACTION_REQUEST_ID":' || case when p_action_request_id is null then 'null' else '"' || replace(p_action_request_id, '"', '\"') || '"' end
            || ',"STATUS":"' || p_status || '","RETRYABLE":' || p_retryable
            || ',"COMPLETED_STEPS":[],"FAILED_STEP":null,"GENERATED_IDENTIFIERS":{}'
            || ',"ERRORS":[{"FIELD":"' || replace(p_field, '"', '\"') || '","CODE":"' || replace(p_code, '"', '\"') || '","MESSAGE":"' || replace(p_message, '"', '\"') || '"}]}';
    end;

    function status_to_http(p_status in varchar2) return number is
    begin
        case p_status
            when 'COMPLETED' then return 200;
            when 'PARTIALLY_COMPLETED' then return 502;
            when 'OUTCOME_UNKNOWN' then return 503;
            when 'MANUAL_REVIEW' then return 503;
            when 'FAILED_NO_SIDE_EFFECT' then return 422;
            when 'IN_PROGRESS' then return 409;
            else return 200;
        end case;
    end;

    function response_status_to_http(
        p_status in varchar2,
        p_response in clob
    ) return number is
    begin
        if p_status = 'FAILED_NO_SIDE_EFFECT'
           and p_response is not null
           and dbms_lob.instr(p_response, 'MFCS_BATCH_WINDOW_ACTIVE') > 0 then
            return 503;
        end if;

        return status_to_http(p_status);
    end;

    procedure submit_transaction(
        p_payload      in clob,
        o_http_status  out number,
        o_response     out clob
    ) is
        l_action_request_id varchar2(80);
        l_operation varchar2(30);
        l_hash varchar2(64);
        l_result varchar2(30);
        l_status varchar2(30);
        l_existing_response clob;
        l_errors clob;
        l_valid boolean;
        l_parsed json_element_t;
        l_payload clob;
    begin
        begin
            l_parsed := json_element_t.parse(p_payload);
        exception
            when others then
                o_http_status := 400;
                o_response := simple_error(null, 'FAILED_NO_SIDE_EFFECT', 'false', '$', 'INVALID_JSON', sqlerrm);
                return;
        end;

        -- Everything below this line works on the canonical document, including
        -- the hash and the row that gets stored. See ie_mfcs_request.normalise_payload.
        l_payload := ie_mfcs_request.normalise_payload(p_payload);

        select json_value(l_payload, '$.ACTION_REQUEST_ID' returning varchar2(80) null on error),
               json_value(l_payload, '$.OPERATION_NAME' returning varchar2(30) null on error)
          into l_action_request_id, l_operation
          from dual;

        if trim(l_action_request_id) is null then
            o_http_status := 400;
            o_response := simple_error(null, 'FAILED_NO_SIDE_EFFECT', 'false', 'ACTION_REQUEST_ID', 'REQUIRED', 'ACTION_REQUEST_ID is required.');
            return;
        end if;

        if trim(l_operation) is null then
            o_http_status := 400;
            o_response := simple_error(l_action_request_id, 'FAILED_NO_SIDE_EFFECT', 'false', 'OPERATION_NAME', 'REQUIRED', 'OPERATION_NAME is required.');
            return;
        elsif l_operation not in ('CREATE_STYLE', 'MODIFY_STYLE', 'CREATE_ORDER', 'MODIFY_ORDER', 'CREATE_ALL') then
            o_http_status := 400;
            o_response := simple_error(l_action_request_id, 'FAILED_NO_SIDE_EFFECT', 'false', 'OPERATION_NAME', 'UNSUPPORTED_OPERATION', 'Unsupported OPERATION_NAME.');
            return;
        end if;

        l_hash := ie_mfcs_request.payload_hash(l_payload);
        ie_mfcs_request.register_request(
            p_action_request_id => l_action_request_id,
            p_operation_name => l_operation,
            p_payload_hash => l_hash,
            p_payload => l_payload,
            o_result => l_result,
            o_status => l_status,
            o_response_payload => l_existing_response
        );

        if l_result = 'CONFLICT' then
            o_http_status := 409;
            o_response := simple_error(l_action_request_id, 'FAILED_NO_SIDE_EFFECT', 'false', 'ACTION_REQUEST_ID', 'IDEMPOTENCY_CONFLICT', 'ACTION_REQUEST_ID already exists with a different business payload hash.');
            return;
        elsif l_result = 'EXECUTING' then
            o_http_status := 409;
            o_response := simple_error(l_action_request_id, 'IN_PROGRESS', 'true', 'ACTION_REQUEST_ID', 'ALREADY_EXECUTING', 'Request is currently executing.');
            return;
        elsif l_result = 'EXISTING' and l_existing_response is not null then
            o_http_status := response_status_to_http(l_status, l_existing_response);
            o_response := l_existing_response;
            return;
        end if;

        l_valid := ie_mfcs_validation.validate_request(l_payload, l_errors);

        if not l_valid then
            o_response := '{"ACTION_REQUEST_ID":"' || replace(l_action_request_id, '"', '\"') || '","STATUS":"FAILED_NO_SIDE_EFFECT","RETRYABLE":false,"COMPLETED_STEPS":[],"FAILED_STEP":null,"GENERATED_IDENTIFIERS":{},"ERRORS":' || l_errors || '}';
            ie_mfcs_request.set_request_status(l_action_request_id, 'FAILED_NO_SIDE_EFFECT', o_response);
            o_http_status := 422;
            return;
        end if;

        ie_mfcs_step.initialize_steps(l_action_request_id, l_operation);
        ie_mfcs_request.set_request_status(l_action_request_id, 'VALIDATED');
        ie_mfcs_orchestrator.execute_request(l_action_request_id);

        select request_status, response_payload
          into l_status, l_existing_response
          from ie_mfcs_prd_request
         where action_request_id = l_action_request_id;

        if l_existing_response is not null then
            o_response := l_existing_response;
        else
            o_response := ie_mfcs_request.build_status_response(l_action_request_id);
        end if;

        o_http_status := response_status_to_http(l_status, o_response);
    exception
        when others then
            o_http_status := 500;
            o_response := simple_error(l_action_request_id, 'FAILED_NO_SIDE_EFFECT', 'true', 'INTEGRATION', to_char(sqlcode), sqlerrm);
    end;

    procedure validate_transaction(
        p_payload      in clob,
        o_http_status  out number,
        o_response     out clob
    ) is
        l_action_request_id varchar2(80);
        l_errors clob;
        l_valid boolean;
        l_payload clob;
    begin
        -- Validate the same document the submit path would store.
        l_payload := ie_mfcs_request.normalise_payload(p_payload);
        select json_value(l_payload, '$.ACTION_REQUEST_ID' returning varchar2(80) null on error)
          into l_action_request_id
          from dual;

        l_valid := ie_mfcs_validation.validate_request(l_payload, l_errors);

        if l_valid then
            o_http_status := 200;
            o_response := '{"ACTION_REQUEST_ID":"' || replace(l_action_request_id, '"', '\"') || '","STATUS":"VALIDATED","RETRYABLE":false,"COMPLETED_STEPS":["VALIDATE_REQUEST"],"FAILED_STEP":null,"GENERATED_IDENTIFIERS":{},"ERRORS":[]}';
        else
            o_http_status := 422;
            o_response := '{"ACTION_REQUEST_ID":' || case when l_action_request_id is null then 'null' else '"' || replace(l_action_request_id, '"', '\"') || '"' end || ',"STATUS":"FAILED_NO_SIDE_EFFECT","RETRYABLE":false,"COMPLETED_STEPS":[],"FAILED_STEP":null,"GENERATED_IDENTIFIERS":{},"ERRORS":' || l_errors || '}';
        end if;
    exception
        when others then
            o_http_status := 400;
            o_response := simple_error(null, 'FAILED_NO_SIDE_EFFECT', 'false', '$', 'INVALID_JSON', sqlerrm);
    end;

    procedure get_transaction(
        p_action_request_id in varchar2,
        o_http_status       out number,
        o_response          out clob
    ) is
        l_status varchar2(30);
        l_response_payload clob;
    begin
        select request_status, response_payload
          into l_status, l_response_payload
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;

        o_http_status := 200;
        if l_response_payload is not null then
            o_response := l_response_payload;
        else
            o_response := ie_mfcs_request.build_status_response(p_action_request_id);
        end if;
    exception
        when no_data_found then
            o_http_status := 404;
            o_response := simple_error(p_action_request_id, 'FAILED_NO_SIDE_EFFECT', 'false', 'ACTION_REQUEST_ID', 'NOT_FOUND', 'Transaction was not found.');
    end;

    procedure resume_transaction(
        p_action_request_id in varchar2,
        o_http_status       out number,
        o_response          out clob
    ) is
        l_status varchar2(30);
        l_response_payload clob;
    begin
        select request_status
          into l_status
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id
         for update nowait;

        if l_status = 'IN_PROGRESS' then
            rollback;
            o_http_status := 409;
            o_response := simple_error(p_action_request_id, 'IN_PROGRESS', 'true', 'ACTION_REQUEST_ID', 'ALREADY_EXECUTING', 'Request is currently executing.');
            return;
        elsif l_status = 'COMPLETED' then
            commit;
            o_http_status := 200;
            select response_payload
              into l_response_payload
              from ie_mfcs_prd_request
             where action_request_id = p_action_request_id;
            if l_response_payload is not null then
                o_response := l_response_payload;
            else
                o_response := ie_mfcs_request.build_status_response(p_action_request_id);
            end if;
            return;
        end if;

        update ie_mfcs_prd_request
           set request_status = 'IN_PROGRESS',
               started_at = coalesce(started_at, systimestamp),
               last_updated_at = systimestamp
         where action_request_id = p_action_request_id;
        commit;

        ie_mfcs_orchestrator.resume_request(p_action_request_id);
        select request_status, response_payload
          into l_status, l_response_payload
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;

        if l_response_payload is not null then
            o_response := l_response_payload;
        else
            o_response := ie_mfcs_request.build_status_response(p_action_request_id);
        end if;
        o_http_status := response_status_to_http(l_status, o_response);
    exception
        when no_data_found then
            o_http_status := 404;
            o_response := simple_error(p_action_request_id, 'FAILED_NO_SIDE_EFFECT', 'false', 'ACTION_REQUEST_ID', 'NOT_FOUND', 'Transaction was not found.');
        when others then
            if sqlcode = -54 then
                o_http_status := 409;
                o_response := simple_error(p_action_request_id, 'IN_PROGRESS', 'true', 'ACTION_REQUEST_ID', 'ALREADY_EXECUTING', 'Request is currently executing.');
            else
                o_http_status := 500;
                o_response := simple_error(p_action_request_id, 'FAILED_NO_SIDE_EFFECT', 'true', 'INTEGRATION', to_char(sqlcode), sqlerrm);
            end if;
    end;
end ie_mfcs_api;
/

-- ==== 20_packages/15_ie_mfcs_ords_util.sql

-- Chunked ORDS response output.

create or replace package ie_mfcs_ords_util authid definer as
    -- Writes a CLOB to the ORDS response in chunks.
    --
    -- htp.prn takes a VARCHAR2, so passing a CLOB larger than 32767 bytes raises
    -- ORA-06502 and ORDS turns that into an opaque HTTP 555. The MFCS item feed
    -- returns roughly 4.6KB per item, so a listing of more than about seven items
    -- crosses that line. Every handler that emits a service response must stream
    -- rather than pass the whole value in one call.
    procedure emit_json(p_body in clob);

    -- Same, for handlers that set an explicit HTTP status.
    procedure emit_json(p_body in clob, p_status in number);
end ie_mfcs_ords_util;
/

create or replace package body ie_mfcs_ords_util as
    c_chunk constant pls_integer := 8000;

    procedure write_body(p_body in clob) is
        l_len number;
        l_off number := 1;
    begin
        if p_body is null then
            htp.prn('{}');
            return;
        end if;
        l_len := dbms_lob.getlength(p_body);
        while l_off <= l_len loop
            htp.prn(dbms_lob.substr(p_body, c_chunk, l_off));
            l_off := l_off + c_chunk;
        end loop;
    end;

    procedure emit_json(p_body in clob) is
    begin
        owa_util.mime_header('application/json', false);
        owa_util.http_header_close;
        write_body(p_body);
    end;

    procedure emit_json(p_body in clob, p_status in number) is
    begin
        owa_util.mime_header('application/json', false);
        owa_util.status_line(p_status, null, false);
        owa_util.http_header_close;
        write_body(p_body);
    end;
end ie_mfcs_ords_util;
/

